-- Node: ap-exc-perforation (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":2,"title":"Perforated Viscus — Surgical Emergency","body":"Rigid abdomen + free air on imaging + sepsis physiology = perforated viscus until proven otherwise. Etiology: peptic ulcer (most common), diverticular, malignancy, ischemic, iatrogenic (post-procedure), foreign body, appendicitis with perforation.\n\n**Next 5 minutes:**\n- **Emergent surgical consult — do not delay for imaging if peritoneal signs + sepsis + free air on bedside CXR/US**\n- IV × 2 large-bore, NS / LR 1-2 L bolus, type and CROSS\n- Broad-spectrum IV antibiotics within 1 h: **piperacillin-tazobactam 4.5 g IV** OR **ceftriaxone 2 g IV + metronidazole 500 mg IV**\n- NPO, NG tube for decompression if obstruction features\n- Foley + monitor UOP\n- Lactate, CBC, CMP, coags, type and CROSS 4 units\n- Imaging: upright CXR (free air under diaphragm — sensitivity ~75%) OR CT abdomen/pelvis with IV contrast (more sensitive for free air, identifies source)\n- Reverse anticoagulation if surgery imminent\n- Pain control (do NOT withhold)\n\n🛑 Do NOT delay surgical consult for confirmatory CT if the patient is septic with peritoneal signs and any concern for perforation. The CT can happen in parallel.\n\n**Special case — boerhaave (esophageal rupture):** vomiting + chest/epigastric pain + sepsis ± subcutaneous emphysema. CT chest/abdomen with oral water-soluble contrast (Gastrografin). Surgical + thoracic consult emergent.","citation":[14],"recommendation":"Emergent surgical consult. Broad-spectrum abx within 1 h. CT abdomen/pelvis. Reverse anticoag.","confidence":"definitive","safetyLevel":"critical"}'::jsonb
WHERE id = 'ap-exc-perforation' AND tree_id = 'abdominal-pain-hub';

