-- Node: ab-stew-sig (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Strong Ion Gap (Unmeasured Anions)","body":"**SIG = Base Deficit + (SID − 35) + 2.5 × (4.2 − Albumin g/dL) − Lactate**\n\nAlternative (Story simplified): **Other Ions = BE − (Na-Cl−35) − (1−Lactate) − 2.5×(4.2−Albumin)**\n\nIf no base excess/deficit is available: use (24.2 − HCO3) as a substitute for base deficit.\n\n**SIG > 2** indicates clinically important **unmeasured anions** are present beyond what Na-Cl, lactate, and albumin can explain. [11]\n\nSee [Stewart Approach Explained](#/info/ab-stewart-explained) for the albumin weak acid effect.","citation":[10,11],"options":[{"label":"SIG ≤ 2 (No significant unmeasured anions)","description":"Disturbance explained by Na-Cl, lactate, and albumin","next":"ab-treatment"},{"label":"SIG > 2 (Unmeasured anions present)","description":"Additional acids beyond measured ions","next":"ab-stew-sig-high","urgency":"urgent"},{"label":"SIG negative","description":"Unmeasured cations or lab artifact","next":"ab-stew-sig-neg"}],"calculatorLinks":[{"id":"stewart-sig","label":"Stewart SID/SIG Calculator"}],"summary":"SIG >2 = unmeasured anions (ketones, uremia, toxic alcohols) beyond Na-Cl, lactate, and albumin"}'::jsonb
WHERE id = 'ab-stew-sig' AND tree_id = 'acid-base';

-- Node: ab-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Treatment Considerations","body":"**Sodium Bicarbonate:**\n[Sodium Bicarbonate](#/drug/sodium-bicarbonate/metabolic acidosis) — indications, dosing, and evidence.\n\n**Indications for bicarbonate:** [12][17]\n• pH ≤ 7.20 with moderate-to-severe AKI (BICAR-ICU: NNT 6 for composite death/organ-failure outcome at day 28, in the AKI subgroup)\n• TCA overdose (sodium channel blockade)\n• Salicylate toxicity (urinary alkalinization)\n• Life-threatening hyperkalemia\n• Bicarbonate-losing conditions (severe diarrhea, RTA)\n\n**Note:** BICAR-ICU enrolled pH ≤ 7.20 + AKIN 2-3. The pH < 6.9 threshold is ADA guidance for DKA specifically.\n\n**NOT recommended:** [3][17]\n• Routine cardiac arrest or CPR\n• Routine DKA (unless pH < 6.9 per ADA)\n• Routine lactic acidosis (no hemodynamic benefit proven)\n\n[Fluid Selection Guide](#/info/ab-fluids-guide) — NS vs balanced crystalloids.","citation":[1,2,3,12,13,17],"next":"ab-disposition","calculatorLinks":[{"id":"anion-gap","label":"Anion Gap"},{"id":"stewart-sig","label":"Stewart SID/SIG"}],"summary":"Bicarb for pH≤7.20 with AKI (BICAR-ICU), TCA OD, salicylate tox, severe hyperK — NOT routine in DKA or lactic acidosis","safetyLevel":"warning"}'::jsonb
WHERE id = 'ab-treatment' AND tree_id = 'acid-base';

-- Node: ai-dispo-icu (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"ICU Admission","body":"**ICU admission criteria:**\n• Active adrenal crisis requiring IV hydrocortisone and vasopressors\n• Persistent hemodynamic instability despite fluid resuscitation\n• Altered mental status\n• Precipitating illness requiring ICU-level care (sepsis, major surgery)\n\n**ICU orders:**\n• [Hydrocortisone](#/drug/hydrocortisone/adrenal crisis) 200 mg/24h — continuous infusion preferred or 50 mg IV q6h\n• Aggressive IV fluids — NS ± D5\n• Glucose monitoring q1-2h (hypoglycemia common)\n• Electrolyte monitoring q4-6h (Na, K)\n• Treat precipitating cause\n• Endocrine consultation\n\nIn-hospital adrenal crisis mortality is approximately 2-6% even with prompt treatment (2.4% in a cohort of 799 hospitalized crisis patients, higher in elderly and pediatric series), and rises significantly with delayed recognition. [2][4]","citation":[2,4,7],"recommendation":"Admit to ICU. Hydrocortisone 200 mg/24h continuous or 50 mg IV q6h. Treat precipitant. Endocrine consultation. Taper steroids as hemodynamics stabilize.","treatment":{"firstLine":{"drug":"Hydrocortisone","dose":"200 mg/24h","route":"IV","frequency":"Continuous infusion (preferred) or 50 mg q6h","duration":"Until hemodynamically stable, then taper to maintenance over 2-3 days","notes":"Add aggressive IV fluids (NS +/- D5). Treat precipitating cause. Endocrine consultation."},"monitoring":"Glucose q1-2h. Electrolytes (Na, K) q4-6h. Hemodynamics continuously. Taper steroids as patient stabilizes."}}'::jsonb
WHERE id = 'ai-dispo-icu' AND tree_id = 'adrenal-insufficiency';

-- Node: anaph-disposition-assess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":6,"title":"Disposition Assessment","body":"[Biphasic Reaction Risk Factors](#/info/anaph-biphasic)\n\n**Biphasic reactions:** ~5-20% of cases, majority occur within 8-10 hours. No deaths have been reported from biphasic reactions. [1][2][3]\n\n**Risk factors for biphasic reaction:**\n• Multiple epinephrine doses required\n• IV fluid bolus needed\n• Delayed initial epinephrine\n• Inhaled beta-agonist required\n• Unknown trigger\n• Initial hypotension\n• Severe initial presentation [2]","citation":[1,2,3],"options":[{"label":"Mild, rapid response to 1 IM epi dose","next":"anaph-dispo-4hr"},{"label":"Required multiple epi doses or IV epi","next":"anaph-dispo-admit","urgency":"urgent"},{"label":"Required intubation / ICU-level care","next":"anaph-dispo-icu","urgency":"critical"}],"summary":"Biphasic reactions 5-20%, mostly within 8-10h — risk factors: multiple epi doses, IV fluids needed, delayed initial epi"}'::jsonb
WHERE id = 'anaph-disposition-assess' AND tree_id = 'anaphylaxis';

