-- Node: awake-contraindications (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":1,"title":"Any Contraindications to Awake Approach?","body":"**Contraindications to Awake Intubation:**\n\n**Absolute:**\n- Uncooperative/severely agitated patient (unable to follow commands)\n- Local anesthetic allergy (rare but ask)\n- Severe airway bleeding (relative — may use VL instead of fiberoptic)\n\n**Relative:**\n- Severely limited time for preparation\n- Full stomach with high aspiration risk\n- Patient refusing procedure\n\n**If Patient Uncooperative:**\nConsider Delayed Sequence Intubation (DSI):\n1. Ketamine 1-2 mg/kg IV for dissociation\n2. Preoxygenate/prepare while dissociated\n3. Then proceed with awake technique once calm\n\n**Any contraindications present?**","citation":[1,2],"options":[{"label":"No contraindications","description":"Proceed with awake approach","next":"awake-prep-overview","urgency":"routine"},{"label":"Patient uncooperative","description":"Consider DSI first","next":"awake-dsi","urgency":"urgent"},{"label":"Severe bleeding / aspiration risk","description":"Modify approach","next":"awake-modified","urgency":"urgent"}],"summary":"Screen for contraindications — uncooperative patient may need DSI first, bleeding favors VL over fiberoptic"}'::jsonb
WHERE id = 'awake-contraindications' AND tree_id = 'awake-intubation';

-- Node: awake-dsi (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Delayed Sequence Intubation (DSI)","body":"**For uncooperative patients who need awake technique but cannot cooperate.**\n\n**DSI Protocol:**\n\n**Step 1: Dissociate**\n- Ketamine 1-2 mg/kg IV push\n- Patient becomes dissociated but maintains breathing\n\n**Step 2: Preoxygenate**\n- Apply non-rebreather or high-flow nasal cannula\n- Patient continues spontaneous ventilation\n- Target SpO2 >95% (or as high as achievable)\n- Takes 3-5 minutes\n\n**Step 3: Topicalize (if time permits)**\n- Nebulized lidocaine while dissociated\n- MAD spray to cords if able to visualize\n\n**Step 4: Intubate**\n- Perform awake intubation technique\n- Patient still breathing but dissociated\n- Confirm visualization before any paralytic\n\n**Key Points:**\n- Ketamine preserves respiratory drive (usually)\n- Watch for apnea/laryngospasm at higher doses\n- Have paralytic and bag-mask ready\n- This is a bridge to awake technique, not RSI\n\n**Proceed to preparation →**","citation":[1,7],"next":"awake-prep-overview","summary":"DSI: ketamine 1-1.5 mg/kg → preoxygenate 3-5min → topicalize if time → awake intubation while still breathing"}'::jsonb
WHERE id = 'awake-dsi' AND tree_id = 'awake-intubation';

