-- Node: ccb-nondhp (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Non-Dihydropyridine CCB Toxicity","body":"**Non-dihydropyridines** (verapamil, diltiazem):\n\n• Block L-type calcium channels in **cardiac tissue**\n• SA node suppression → bradycardia\n• AV node blockade → conduction delays\n• Myocardial depression → reduced contractility\n• Shock phenotype: **CARDIOGENIC** (cool extremities, poor CO, elevated lactate) [1][2]\n\n[Verapamil](#/drug/verapamil/overdose toxicity) is the most cardiotoxic:\n• Greatest negative inotropic effect\n• Most deaths occur with verapamil overdose [3]\n\n**Treatment emphasis:** High-dose insulin euglycemia therapy (HIET) + inotropes [1][2].","citation":[1,2,3],"next":"ccb-extended-release","summary":"Verapamil is most cardiotoxic — cardiogenic shock with bradycardia and conduction delays"}'::jsonb
WHERE id = 'ccb-nondhp' AND tree_id = 'ccb-od';

-- Node: ccb-initial-stab (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Initial Stabilization","body":"**Immediate actions:**\n• ABCs, two large-bore IVs\n• Continuous cardiac monitor\n• 12-lead ECG (bradycardia, conduction delays)\n• Labs: BMP, lactate, glucose (hyperglycemia supports diagnosis)\n• Consider central line and arterial line early\n\n**[Atropine](#/drug/atropine/ccb toxicity)** 0.5-1 mg IV:\n• Usually **ineffective** — toxicity is at the calcium channel, not vagal\n• May try, but do not delay other interventions [1][3]\n\n**Transcutaneous pacing:**\n• Temporizing measure\n• Often fails to capture or improve BP due to impaired contractility\n• Do not rely on pacing alone [1]","citation":[1,3],"next":"ccb-calcium","summary":"Atropine and pacing usually fail — toxicity is at the calcium channel, not vagal"}'::jsonb
WHERE id = 'ccb-initial-stab' AND tree_id = 'ccb-od';

