-- Node: chf-scape-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"SCAPE: Immediate Treatment","body":"**SCAPE is NOT volume overload.** The problem is fluid redistribution into lungs from massive afterload. Treatment = break the sympathetic spiral.\n\n**Simultaneous actions (do ALL at once):**\n\n**1. BiPAP/CPAP — Immediate**\n- Start CPAP 8-10 cm H₂O OR BiPAP 12/6\n- Titrate UP aggressively: goal CPAP 15-20 or BiPAP 20-24/10-12\n- Higher pressures = greater hemodynamic benefit\n- Reduces preload AND afterload\n\n**2. High-Dose [Nitroglycerin](#/drug/nitroglycerin/scape) — Aggressive**\n- **See NTG Protocol**\n- Bolus: 400-800 mcg/min x 2-2.5 min (OR 1000-2000 mcg IV bolus)\n- Then infusion: start 100-200 mcg/min, titrate to 400+ mcg/min\n- Goal: SBP <140 within 10 minutes\n\n**By 10 minutes, patient should be \"out of the water.\"** [1][3]","citation":[1,3],"next":"chf-scape-avoid","treatment":{"firstLine":{"drug":"Nitroglycerin","dose":"400-800 mcg/min x 2-2.5 min bolus, then 100-200 mcg/min infusion","route":"IV","frequency":"Continuous infusion","duration":"Until SBP <140 and symptoms improve","notes":"Titrate to 400+ mcg/min as needed. No ceiling dose in SCAPE. Goal SBP <140 within 10 minutes."},"alternative":{"drug":"BiPAP","dose":"Start 12/6, titrate to 20-24/10-12","route":"Non-invasive ventilation","frequency":"Continuous","duration":"Until work of breathing improves","notes":"Use simultaneously with NTG. Higher pressures = greater hemodynamic benefit."},"monitoring":"BP every 2-5 min during titration. SpO2, respiratory effort, mental status. Watch for hypotension as SCAPE breaks."},"calculatorLinks":[{"id":"chf-ntg-calc","label":"SCAPE NTG Calculator"},{"id":"chf-bipap","label":"BiPAP Quick Start"}],"summary":"Simultaneous BiPAP + high-dose NTG — patient should be out of the water by 10 minutes","safetyLevel":"critical"}'::jsonb
WHERE id = 'chf-scape-treatment' AND tree_id = 'chf-exacerbation';

-- Node: chf-scape-avoid (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"SCAPE: What to AVOID","body":"**Critical: These can HARM your SCAPE patient:**\n\n| Agent | Why Harmful |\n|-------|-------------|\n| **Beta-blockers** | Impair pump function — absolutely contraindicated |\n| **Morphine** | MIMO RCT: significantly more cardiovascular serious adverse events (cardiac arrest, cardiogenic shock) vs midazolam |\n| **Routine diuretics** | Only if TRUE volume overload. Many SCAPE patients are intravascularly depleted |\n\n**When to give diuretics in SCAPE:**\n- Only AFTER vasodilator therapy working\n- Only if evidence of true volume overload (weight gain, weeks of edema)\n- Use low dose initially (20-40 mg furosemide)\n\n**Intubation:**\n- AVOID if possible — these patients often turn around dramatically\n- BiPAP buys time for NTG to work\n- If must intubate: ketamine > propofol (less hypotension) [1][3]","citation":[1,3],"next":"chf-scape-response","summary":"No beta-blockers, no morphine (MIMO trial: increased arrest), no routine diuretics in SCAPE","safetyLevel":"critical"}'::jsonb
WHERE id = 'chf-scape-avoid' AND tree_id = 'chf-exacerbation';

-- Node: chf-diuretic-strategy (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Diuretic Strategy — Warm & Wet","body":"**Goal:** Reduce intravascular volume, relieve congestion.\n\n**IV Loop Diuretic ([Furosemide](#/drug/furosemide/volume overload)):**\n- **Dose:** 1-2.5x home oral dose IV\n- If no home diuretic: start 40-80 mg IV\n- If home dose >80 mg: give 1-2x as IV\n\n**Monitoring targets:**\n- Urine output: >100-150 mL/hr by 6 hours\n- Urine spot sodium: >50-70 mEq/L at 2 hours\n- Daily weight loss: 0.5-1 kg/day\n\n**Bolus vs Infusion:**\n- DOSE trial: no significant difference\n- Bolus q8-12h often sufficient\n- Infusion (5-10 mg/hr) if high-dose needed\n\n**Adjunctive vasodilator:**\n- Add NTG if SBP >100 for faster symptom relief\n- Reduces preload, speeds diuresis [2][4]","citation":[2,4],"next":"chf-diuretic-response","treatment":{"firstLine":{"drug":"Furosemide","dose":"40-80 mg IV (or 1-2.5x home oral dose)","route":"IV","frequency":"q8-12h bolus OR 5-10 mg/hr infusion","duration":"Until euvolemic (target -0.5 to -1 kg/day)","notes":"If home dose >80 mg PO, give 1-2x as IV. Monitor urine output target >100-150 mL/hr."},"alternative":{"drug":"Bumetanide","dose":"1-2 mg IV (40:1 furosemide:bumetanide)","route":"IV","frequency":"q8-12h","duration":"Until euvolemic","notes":"Alternative loop diuretic. Better bioavailability than furosemide."},"monitoring":"Urine output q1-2h, daily weights, electrolytes (K+, Mg++) q12-24h, creatinine daily. Spot urine Na >50-70 mEq/L at 2h indicates adequate response."},"calculatorLinks":[{"id":"chf-lasix-calc","label":"Lasix Dose Calculator"}],"summary":"Furosemide 1-2.5x home dose IV — target urine output >100-150 mL/hr by 6 hours"}'::jsonb
WHERE id = 'chf-diuretic-strategy' AND tree_id = 'chf-exacerbation';

-- Node: croup-mild-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Mild Croup — Glucocorticoid Only","body":"**Single dose glucocorticoid is standard of care for ALL severities of croup.**\n\n**First-line:**\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.6 mg/kg PO** (max 16 mg) — single dose\n\n**Non-inferior alternatives:**\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.15 mg/kg PO** — lower dose equally effective [3][6]\n• [Prednisolone](#/drug/prednisolone/pediatric croup) **1 mg/kg PO** — non-inferior symptom relief, BUT higher re-presentation rate (29% vs 7% with dex) [6]\n\n**If unable to tolerate oral:**\n• [Budesonide](#/drug/budesonide-neb/pediatric croup) **2 mg nebulized** — effective alternative [5][9]\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.6 mg/kg IM**\n\n**NNT = 7** to prevent one return visit. Reduces return visits/readmissions by ~50%. Safe single-dose profile.","citation":[1,2,3,5,6,8],"next":"croup-mild-obs","summary":"Dexamethasone 0.6 mg/kg PO single dose for ALL severities — NNT 7 to prevent return visit"}'::jsonb
WHERE id = 'croup-mild-tx' AND tree_id = 'croup';

-- Node: croup-mod-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Moderate Croup — Dexamethasone + Epinephrine","body":"**Step 1: Glucocorticoid**\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.6 mg/kg PO/IM** (max 16 mg) — single dose\n\n**Step 2: Nebulized Epinephrine**\n• [Racemic Epinephrine](#/drug/racemic-epinephrine/pediatric croup) **0.5 mL of 2.25%** in 4.5 mL normal saline\n• OR L-epinephrine **0.5 mL/kg of 1:1000** (max 5 mL) nebulized\n\nEpinephrine provides rapid but **temporary** relief (onset minutes, duration 1-2 hours). Must observe minimum 2 hours after administration.\n\n**Keep child calm** — agitation worsens airway obstruction.","citation":[2,4,7],"next":"croup-epi-obs","summary":"Dex + racemic epi 0.5mL of 2.25% nebulized — onset minutes, duration 1-2h, observe minimum 2h"}'::jsonb
WHERE id = 'croup-mod-tx' AND tree_id = 'croup';

-- Node: croup-severe-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe Croup — Aggressive Treatment","body":"**Step 1: Glucocorticoid**\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.6 mg/kg PO/IM** (max 16 mg) — single dose\n\n**Step 2: Nebulized Epinephrine**\n• [Racemic Epinephrine](#/drug/racemic-epinephrine/pediatric croup) **0.5 mL of 2.25%** in 4.5 mL NS\n• OR L-epinephrine **0.5 mL/kg of 1:1000** (max 5 mL) neb\n• **May repeat epinephrine** — repeated doses can prevent intubation in many cases [4]\n\n**Additional considerations:**\n• Heliox (70:30 He:O₂) — may provide short-term benefit when combined with dex, but limited evidence [11]\n• Continuous monitoring with pulse oximetry\n• **Minimize interventions that cause agitation** — crying worsens obstruction\n• Have airway equipment at bedside","citation":[2,4,7,11],"next":"croup-epi-obs","summary":"Repeat epinephrine may prevent intubation — minimize agitation, have airway equipment ready"}'::jsonb
WHERE id = 'croup-severe-tx' AND tree_id = 'croup';

-- Node: croup-failure-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Impending Respiratory Failure","body":"**This is a clinical emergency — activate airway team.**\n\n**Immediate interventions:**\n• [Dexamethasone](#/drug/dexamethasone/pediatric croup) **0.6 mg/kg IM** (if not already given)\n• [Racemic Epinephrine](#/drug/racemic-epinephrine/pediatric croup) nebulized — may repeat\n• **Blow-by oxygen** — do NOT agitate the child\n• **Call anesthesia/ENT for airway backup**\n\n**Airway management:**\n• Use endotracheal tube **0.5-1.0 size smaller** than age-predicted (subglottic narrowing)\n• Oral intubation preferred — may need smaller tube than expected\n• Have surgical airway equipment available\n\n**Rule out alternative diagnoses:** bacterial tracheitis, epiglottitis, foreign body, peritonsillar abscess.","citation":[2,4],"next":"croup-icu","summary":"ETT 0.5-1.0 size SMALLER than age-predicted — subglottic narrowing, call anesthesia/ENT backup","safetyLevel":"critical"}'::jsonb
WHERE id = 'croup-failure-tx' AND tree_id = 'croup';

-- Node: croup-repeat-epi (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Repeat Nebulized Epinephrine","body":"**Repeat nebulized epinephrine** at same dose:\n• [Racemic Epinephrine](#/drug/racemic-epinephrine/pediatric croup) **0.5 mL of 2.25%** in 4.5 mL NS\n• OR L-epinephrine **0.5 mL/kg of 1:1000** (max 5 mL) neb\n\n**Repeated doses may prevent intubation** in many cases. [4]\n\nRestart 2-hour observation clock after each dose.\n\n**Escalation considerations:**\n• Multiple doses of epinephrine → strong indicator for admission\n• If requiring >2 doses → consider ICU level monitoring\n• **Failure to improve with dexamethasone + epinephrine** → consider alternative diagnoses (bacterial tracheitis, foreign body)","citation":[4],"next":"croup-re-obs","summary":"Repeat epi at same dose — restart 2h observation clock; >2 doses = strong indicator for admission"}'::jsonb
WHERE id = 'croup-repeat-epi' AND tree_id = 'croup';

-- Node: dic-isth-score (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"ISTH Overt DIC Score","body":"[ISTH DIC Calculator](#/calculator/dic-isth-score)\n\n**ISTH 2001 criteria (validated and updated 2025):** [4][5]\n\n| Parameter | 0 | 1 | 2 | 3 |\n|-----------|---|---|---|---|\n| Platelets (×10⁹/L) | >100 | 50-100 | <50 | — |\n| Fibrin marker (D-dimer/FDP) | No rise | — | Moderate | Strong |\n| PT prolongation | <3 s | 3-6 s | >6 s | — |\n| Fibrinogen (g/L) | ≥1 | <1 | — | — |\n\n**Interpretation:** [5]\n• **≥5** = compatible with overt DIC; repeat daily for trend\n• **<5** = suggests non-overt DIC; repeat in 1-2 days\n\n**Performance:** [5]\n• Sensitivity 91%, specificity 97% for overt DIC vs no DIC\n• 25% mortality difference for each 1-point increase\n\n**Limitations:** [4]\n• Less sensitive than JAAM in early sepsis-DIC\n• Captures decompensated state — non-overt DIC may be missed\n• Does not directly inform anticoagulation vs hemostatic decisions","citation":[4,5],"next":"dic-jaam-score","calculatorLinks":[{"id":"dic-isth-score","label":"ISTH DIC Score"}],"summary":"ISTH ≥5 = overt DIC; sens 91% / spec 97%; less sensitive in early sepsis-DIC than JAAM"}'::jsonb
WHERE id = 'dic-isth-score' AND tree_id = 'dic';

-- Node: dic-sic-score (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"SIC (Sepsis-Induced Coagulopathy) Score","body":"[SIC Calculator](#/calculator/dic-sic-score)\n\n**Sepsis-Induced Coagulopathy (SIC) score — Iba 2017:** [8]\n\n| Parameter | 0 | 1 | 2 |\n|-----------|---|---|---|\n| Platelets (×10⁹/L) | ≥150 | 100-150 | <100 |\n| INR | ≤1.2 | 1.2-1.4 | >1.4 |\n| Total SOFA (resp + CV + hep + renal, max 12) | 0 | 1 | ≥2 |\n\n**Interpretation:** [8]\n• **≥4 (with platelet + INR subscore ≥3)** = SIC\n• Identifies septic patients at risk for **progression** to overt DIC\n• Candidate population for anticoagulation trials (recombinant thrombomodulin, antithrombin)\n\n**Why it matters:** [4][8]\n• Designed as an **earlier, simpler** predictor than JAAM/ISTH\n• Decouples decision-making from full overt DIC criteria\n• ISTH 2025 endorsed two-step approach: SIC first → if positive, ISTH score next\n\n**Cite:** Iba T, et al. JTH 2017;15:518-26.","citation":[4,8],"next":"dic-trends","calculatorLinks":[{"id":"dic-sic-score","label":"SIC Score"}],"summary":"SIC ≥4 (with plt+INR ≥3) = sepsis-induced coagulopathy → predicts progression to overt DIC; candidate for anticoag trials"}'::jsonb
WHERE id = 'dic-sic-score' AND tree_id = 'dic';

-- Node: dic-trends (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Serial Monitoring & Trends","body":"**ISTH 2025:** Trends in scores predict outcome better than single snapshots. [4]\n\n**Recommended monitoring schedule:** [2][4]\n\n| Phase | Frequency |\n|-------|-----------|\n| Resuscitation / active bleeding | CBC, PT/PTT, fibrinogen q4-6h |\n| Stabilization | q12h |\n| Recovery | q24h |\n\n**Concerning trends:** [4]\n• Platelet drop >30% in 24 hours\n• Rising D-dimer despite trigger control\n• Falling fibrinogen below acute-phase baseline\n• Worsening organ function (rising creatinine, lactate)\n\n**Reassuring trends:** [4]\n• Platelets recovering (typically lag 24-48h after trigger control)\n• D-dimer falling\n• Fibrinogen rising back above 2 g/L\n• Organ function stabilizing\n\n**Pearl:** Fibrinogen is usually the **last** parameter to normalize. Don''t prematurely declare DIC resolved on platelet count alone. [4]","citation":[2,4],"next":"dic-non-overt","summary":"Monitor q4-6h while resuscitating; trend matters more than absolute value; fibrinogen is last to normalize"}'::jsonb
WHERE id = 'dic-trends' AND tree_id = 'dic';

-- Node: dic-heparin (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Heparin in DIC","body":"**Heparin in DIC is highly selective and never first-line.** [4][9][14]\n\n**Consider heparin (or LMWH) ONLY if:** [4][9][14]\n• **Thrombotic-dominant phenotype** without active bleeding\n• Macrovascular thrombosis (DVT, PE, arterial occlusion)\n• Trousseau syndrome (cancer-associated thrombosis) — LMWH is first-line\n• Purpura fulminans / extensive microvascular thrombosis\n\n**AVOID heparin in:** [4][11][12]\n• Bleeding-dominant DIC\n• APL\n• Obstetric DIC with active hemorrhage\n• Recent surgery / trauma with bleeding risk\n• Severe thrombocytopenia (<50 × 10⁹/L)\n• Suspected HIT\n\n**Dosing (when indicated):** [9][14]\n• LMWH (enoxaparin) 1 mg/kg SC q12h or 1.5 mg/kg SC daily\n• Unfractionated heparin: 5000 unit bolus then 500-1000 units/hr (titrate to aPTT 1.5-2.5× control); some experts use lower-dose continuous (300-500 units/hr) without bolus\n• Renal adjust (CrCl <30): UFH preferred over LMWH\n\n**Monitoring:** [9]\n• aPTT or anti-Xa\n• Platelet count for HIT\n• Bleeding\n\n**Pearl:** Most modern DIC guidelines (ISTH 2025) reserve heparin for clear macrovascular or microvascular thrombosis. Do NOT use empirically. [4]","citation":[4,9,11,12,14],"next":"dic-tranexamic","summary":"Heparin only if thrombotic-dominant + no bleeding; LMWH for Trousseau; AVOID in APL, obstetric bleeding, severe thrombocytopenia"}'::jsonb
WHERE id = 'dic-heparin' AND tree_id = 'dic';

-- Node: dic-antithrombin-tm (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Antithrombin & Recombinant Thrombomodulin","body":"**Specialty agents — not standard in US emergency care, but increasingly studied.** [4][8][9]\n\n**Antithrombin (AT) concentrate:** [9]\n• Rationale: AT is consumed in DIC; replacement may restore endogenous anticoagulation\n• KyberSept trial (sepsis): no overall mortality benefit; subgroup with DIC and no concurrent heparin showed signal\n• Used in Japan and some European centers; not widely used in US\n• Dose: 30 IU/kg/day × 4 days (when used)\n\n**Recombinant thrombomodulin (rTM, ART-123):** [4][8]\n• Rationale: Activates protein C, suppresses inflammation, modulates coagulation\n• SCARLET trial (2019): no overall 28-day mortality benefit in sepsis-DIC\n• Approved in Japan; not FDA-approved in US\n• Subgroup analysis: possible benefit in patients with severe coagulopathy and not on concurrent heparin\n• Dose: 0.06 mg/kg/day × 6 days (when used)\n\n**Activated Protein C (drotrecogin alfa):** [9]\n• Withdrawn from market in 2011 after PROWESS-SHOCK showed no benefit and increased bleeding\n\n**ISTH 2025 stance:** [4]\n• rTM and AT may be considered in select sepsis-DIC patients in regions where available\n• Not standard of care in US\n• Decision should involve hematology / critical care\n\n**Pearl:** Trigger control + supportive care remain the mainstays. Anticoagulant therapies are adjunctive at best. [4]","citation":[4,8,9],"next":"dic-supportive","summary":"AT concentrate and rTM are specialty agents — not US standard; SCARLET (rTM) and KyberSept (AT) negative overall but signals in DIC subgroups","skippable":true}'::jsonb
WHERE id = 'dic-antithrombin-tm' AND tree_id = 'dic';

