-- Node: eclampsia-prophylaxis (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Seizure Prophylaxis","body":"**Magnesium for seizure prophylaxis in severe preeclampsia:** [1,4]\n\n**Indications for prophylaxis:**\n- Preeclampsia with severe features\n- HELLP syndrome\n- Active labor in patient with preeclampsia\n- Planned delivery in severe preeclampsia\n\n**Prophylaxis protocol:**\n- Loading: 4g IV over 20 minutes\n- Maintenance: 1-2g/hour IV\n- Continue 24-48 hours postpartum\n\n**NNT (Number Needed to Treat):** [4]\n- Severe preeclampsia: NNT = 50-100 to prevent 1 eclamptic seizure\n- MAGPIE trial: 58% reduction in eclampsia risk (RR 0.42, 95% CI 0.29-0.60)\n\n**Controversial areas:**\n- Mild preeclampsia: benefit less clear\n- Individual risk assessment warranted\n\n**Alternative if magnesium contraindicated:**\n- Phenytoin (loading 10-15 mg/kg, max rate 50 mg/min)\n- Less effective than magnesium\n- Use only if true magnesium allergy or severe toxicity","citation":[1,4],"next":"eclampsia-bp-assessment","summary":"Mag prophylaxis for severe preeclampsia: 4g IV load then 1-2g/hr, NNT 50-100","skippable":true}'::jsonb
WHERE id = 'eclampsia-prophylaxis' AND tree_id = 'eclampsia';

-- Node: fti-whitlow (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Herpetic Whitlow - Recognize, Do NOT Incise","body":"See [Photo Atlas - Whitlow](#/info/fti-photo-atlas).\n\n**Recognition:**\n- Grouped **clear vesicles on an erythematous base**, often coalescing.\n- Burning/throbbing pain typically out of proportion to exam early on.\n- Prodrome: tingling 24-48 h before vesicles appear.\n- High-risk groups: dental/respiratory therapy workers, kids who suck thumbs, healthcare workers; HSV-1 > HSV-2.\n- Self-limited 2-4 weeks. Recurrences possible.\n\n**Why it matters:**\n- **DO NOT incise.** Incision causes bacterial superinfection, viremia, and slower healing. This is the most common ED error in fingertip infections.\n- Often misdiagnosed as felon or paronychia early - the **vesicles** are the clue.\n\n**Confirmatory testing (only if diagnosis uncertain):**\n- HSV PCR from de-roofed vesicle fluid (most sensitive).\n- Tzanck smear: multinucleated giant cells (low sensitivity, fast).\n- Viral culture (slow, less commonly available).\n\n**Treatment:**\n- **[Acyclovir](#/drug/acyclovir/herpes-simplex)** 400 mg PO TID (or 200 mg 5x/day) x 7-10 days, OR **[Valacyclovir](#/drug/valacyclovir/herpes-simplex)** 1 g PO BID x 7-10 days. Immunocompromised: acyclovir 400 mg 3-5x/day until resolution.\n- Most benefit if started **within 48 h** of vesicle onset.\n- Dry occlusive dressing to prevent autoinoculation/spread to others.\n- Analgesia.\n\n**Suppression** for >=6 recurrences/year: **[Acyclovir](#/drug/acyclovir/herpes-simplex)** 400 mg BID or **[Valacyclovir](#/drug/valacyclovir/herpes-simplex)** 500 mg daily. [7,8]","citation":[7,8],"next":"fti-disposition-outpatient","images":[{"src":"images/fingertip-infections/herpetic-whitlow.jpg","alt":"Herpetic whitlow with grouped clear vesicles on erythematous base","caption":"Herpetic whitlow: grouped clear vesicles on an erythematous base. DO NOT incise — causes superinfection. (CC, Wikimedia Commons)"}]}'::jsonb
WHERE id = 'fti-whitlow' AND tree_id = 'fingertip-infections';

-- Node: gib-exc-ibd (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"IBD Flare with Bleeding","body":"Open [IBD Flare](#/tree/ibd-flare) consult. UC and Crohn flares can present with significant lower GI bleed; severe UC flare is its own emergency.\n\n**Recognize severe flare (Truelove-Witts):** [16]\n\n- ≥6 bloody stools/day\n- AND any of: temp >37.8°C, HR >90, Hgb <10.5 g/dL, ESR >30\n\n**Workup:**\n\n- CBC, CMP, ESR, CRP, lactate, blood cultures if febrile\n- Stool studies: C. diff PCR + bacterial pathogens + ova/parasites (C. diff coinfection up to 5% in severe flare)\n- KUB or CT to assess for toxic megacolon (transverse colon >6 cm), perforation\n- Gastroenterology + colorectal surgery consult for severe flare\n\n**Treatment in ED:**\n\n- IV methylprednisolone 60 mg IV once daily (or hydrocortisone 100 mg IV q6h) — equivalent regimens per ACG severe UC guideline; methylprednisolone is dosed as a 60 mg/day total, NOT q6h\n- IV fluids, transfuse if Hgb <7 (8 in cardiac)\n- Empirical antibiotics if febrile or perforation suspected (ceftriaxone + metronidazole)\n- Hold all anti-motility agents (loperamide, diphenoxylate, anticholinergics) — can precipitate toxic megacolon\n- DVT prophylaxis (IBD flare carries high VTE risk even with active bleeding — controversial but recommended in stable bleeding per ACG)\n\n**Refractory:** infliximab or cyclosporine rescue within 3-5 days; colectomy if no response.","citation":[16,17],"summary":"Open [IBD Flare](#/tree/ibd-flare) consult. Truelove-Witts for severity. Hold anti-motility. C. diff coinfection always.","safetyLevel":"critical"}'::jsonb
WHERE id = 'gib-exc-ibd' AND tree_id = 'gi-bleed-hub';

-- Node: hs-ice-packs (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Ice Pack Cooling (Suboptimal)","body":"**LEAST effective method — cooling rate ~0.05°C/min** [2]\n\n**If this is all you have:**\n• Place ice packs to axillae, groin, neck, and entire torso\n• Wet sheets over patient + fans\n• Cold IV fluids (4°C NS)\n• Rotate ice packs frequently (they warm up)\n\n**Consider transfer** to facility with immersion or evaporative capability if cooling is inadequate.\n\n**Avoid:**\n• Cooling blankets alone (too slow)\n• Antipyretics ([Acetaminophen](#/drug/acetaminophen/fever) and NSAIDs are USELESS — thermoregulatory setpoint is normal) [1][2]","citation":[1,2],"next":"hs-cooling-endpoint","treatment":{"firstLine":{"drug":"Ice packs","dose":"To axillae, groin, neck, entire torso","route":"External","frequency":"Rotate frequently as they warm","duration":"Until core temp reaches 39°C","notes":"Least effective method. Consider transfer if inadequate cooling."},"monitoring":"Continuous rectal temp. Target: <39°C within 30 min — may not be achievable with this method."},"summary":"Ice packs to neck, axillae, groin as adjunct — least effective alone, use with other methods","skippable":true}'::jsonb
WHERE id = 'hs-ice-packs' AND tree_id = 'heat-stroke';

-- Node: hs-intubation (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Intubation Considerations","body":"**RSI for heat stroke:**\n\n**Induction:** [Ketamine](#/drug/ketamine/RSI induction) 1-2 mg/kg IV or [Propofol](#/drug/propofol/RSI induction) 1-2 mg/kg IV\n\n**Paralysis:** [Rocuronium](#/drug/rocuronium/RSI intubation) 1.2 mg/kg IV\n• **AVOID succinylcholine** — hyperkalemia risk with rhabdomyolysis\n\n**Post-intubation:**\n• Continue active cooling\n• Target normocapnia (avoid hyperventilation)\n• Sedation: propofol or midazolam + fentanyl [2]","citation":[2],"next":"hs-seizures","treatment":{"firstLine":{"drug":"Rocuronium","dose":"1.2 mg/kg","route":"IV","frequency":"Once for RSI","duration":"Single dose","notes":"AVOID succinylcholine — hyperkalemia risk with rhabdomyolysis."},"monitoring":"Continue active cooling post-intubation. Target normocapnia."},"summary":"Intubate for airway protection in severe AMS — continue cooling after intubation"}'::jsonb
WHERE id = 'hs-intubation' AND tree_id = 'heat-stroke';

-- Node: hs-seizure-rx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Seizure Treatment","body":"**First-line:** [Midazolam](#/drug/midazolam/status epilepticus) 0.2 mg/kg IV or IM (max 10 mg)\n\n**Alternative:** [Lorazepam](#/drug/lorazepam/status epilepticus) 0.1 mg/kg IV (max 4 mg)\n\n**If refractory:**\n• [Propofol](#/drug/propofol/refractory se) infusion or\n• [Phenobarbital](#/drug/phenobarbital/status epilepticus) 20 mg/kg IV\n\n**Avoid phenytoin/fosphenytoin** — may worsen hyperthermia and is less effective for toxin-induced seizures.\n\n**Continue aggressive cooling** — seizures generate significant heat. [2][3]","citation":[2,3],"next":"hs-complications","treatment":{"firstLine":{"drug":"Midazolam","dose":"0.2 mg/kg IV or IM (max 10 mg)","route":"IV or IM","frequency":"May repeat in 5 minutes","duration":"Until seizures controlled","notes":"IM route useful if no IV access. Continue cooling."},"alternative":{"drug":"Lorazepam","dose":"0.1 mg/kg IV (max 4 mg)","route":"IV","frequency":"May repeat in 5 minutes","duration":"Until seizures controlled","notes":"Alternative to midazolam. Avoid phenytoin."},"monitoring":"Respiratory status, continue cooling. EEG if refractory."},"summary":"Benzodiazepines first-line for heat stroke seizures — seizure activity generates more heat","safetyLevel":"warning"}'::jsonb
WHERE id = 'hs-seizure-rx' AND tree_id = 'heat-stroke';

-- Node: hs-rhabdo-severe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Severe Rhabdomyolysis","body":"**CK >40,000 — high risk for AKI and dialysis** [2]\n\n**Management:**\n• Same as moderate rhabdo but more aggressive fluids\n• Early nephrology consult\n• Consider dialysis if:\n  - Refractory hyperkalemia (K+ >6.5)\n  - Severe metabolic acidosis\n  - Volume overload despite diuresis\n  - Anuria\n\n**Monitor for compartment syndrome:**\n• Pain out of proportion\n• Pain with passive stretch\n• Tense compartments\n• → Emergent fasciotomy if present [2]","citation":[2],"next":"hs-coags","treatment":{"firstLine":{"drug":"Aggressive crystalloid","dose":"Target UOP 200-300 mL/hr","route":"IV","frequency":"Continuous","duration":"Until CK trending down or dialysis initiated","notes":"Early nephrology consult. May need emergent dialysis."},"monitoring":"CK q6h, Cr, K+, ABG. Continuous cardiac monitoring for hyperkalemia."},"summary":"CK >40,000: continuous IV fluids, monitor for compartment syndrome and AKI","safetyLevel":"critical"}'::jsonb
WHERE id = 'hs-rhabdo-severe' AND tree_id = 'heat-stroke';

-- Node: hs-disposition (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":5,"title":"Disposition","body":"**ALL heat stroke patients require admission** — multi-organ dysfunction can be delayed 24-72 hours. [2][3]\n\nAssess severity to determine level of care.","citation":[2,3],"options":[{"label":"Rapid cooling achieved, stable, mild organ dysfunction","next":"hs-admit-floor"},{"label":"Ongoing hypotension, significant organ dysfunction","next":"hs-admit-icu","urgency":"urgent"},{"label":"Intubated, vasopressors, or refractory","next":"hs-admit-icu","urgency":"critical"}],"summary":"ALL heat stroke patients require admission — mild/stable to floor, unstable/organ dysfunction to ICU"}'::jsonb
WHERE id = 'hs-disposition' AND tree_id = 'heat-stroke';

-- Node: shock-neurogenic (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Neurogenic Shock","body":"**Neurogenic shock** = loss of sympathetic tone from spinal cord injury (usually T6 and above).\n\n**Classic triad:**\n• Hypotension\n• Bradycardia (unlike other shock types)\n• Warm, dry skin (peripheral vasodilation)\n\n**Management:**\n\n**1. Volume resuscitation:**\n• Cautious fluids — may worsen spinal cord edema\n• 1-2 L crystalloid, reassess\n\n**2. Vasopressors:**\n• [Norepinephrine](#/drug/norepinephrine/shock) preferred (alpha > beta)\n• Target MAP ≥85-90 mmHg for spinal cord perfusion\n\n**3. Bradycardia:**\n• [Atropine](#/drug/atropine/bradycardia) 1 mg IV\n• Temporary pacing if refractory\n\n**4. Spinal precautions** — do NOT move without immobilization","citation":[1],"next":"hypotension-disposition","treatment":{"firstLine":{"drug":"Norepinephrine","dose":"0.05-0.3 mcg/kg/min","route":"IV","frequency":"Continuous","duration":"Until resolved","notes":"Target MAP ≥85-90 mmHg for spinal cord perfusion. Alpha-agonist preferred."},"alternative":{"drug":"Atropine","dose":"1 mg","route":"IV","frequency":"Every 3-5 min, max 3 mg","duration":"For symptomatic bradycardia","notes":"Fixed 1 mg push per current AHA ACLS dosing (replaces older 0.5 mg incremental regimen). May need transcutaneous pacing if refractory."},"monitoring":"MAP target 85-90 mmHg. Heart rate. Neurologic exam."},"summary":"Bradycardia + hypotension + warm skin; MAP target 85-90 for cord perfusion; norepinephrine + atropine","safetyLevel":"warning"}'::jsonb
WHERE id = 'shock-neurogenic' AND tree_id = 'hypotension-workup';

-- Node: shock-hemorrhagic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Hemorrhagic Shock","body":"**Hemorrhagic shock requires source control + blood products.**\n\n**Massive Transfusion Protocol (MTP):**\n• Activate if shock index >1 + ongoing bleeding\n• Target **1:1:1 ratio** (pRBC : FFP : platelets)\n\n**Tranexamic Acid (TXA):**\n• [TXA](#/drug/tranexamic-acid/hemorrhage) 1 g IV over 10 min within 3 hours of injury\n• Then 1 g over 8 hours\n\n**Source control:**\n• Trauma → OR, IR, damage control surgery\n• GI bleed → endoscopy, IR embolization\n• Ruptured AAA → emergent vascular surgery\n• Ectopic → emergent OB/GYN\n\n**Permissive hypotension (trauma):**\n• Target SBP 80-90 mmHg until surgical control\n• Exception: TBI — maintain SBP >100","citation":[1,9],"next":"hypotension-disposition","treatment":{"firstLine":{"drug":"Packed RBCs + FFP + Platelets","dose":"1:1:1 ratio","route":"IV","frequency":"Per MTP","duration":"Until hemorrhage controlled","notes":"Activate MTP if shock index >1 with ongoing bleeding."},"alternative":{"drug":"Tranexamic Acid","dose":"1 g IV over 10 min, then 1 g over 8h","route":"IV","frequency":"See dosing","duration":"Single dosing","notes":"Give within 3 hours of injury onset. No benefit if >3 hours."},"monitoring":"Serial Hgb. Coags (TEG if available). Lactate. Source control confirmation."},"summary":"MTP 1:1:1 ratio; TXA 1g within 3h; permissive hypotension (SBP 80-90) until source control; TBI exception","safetyLevel":"critical"}'::jsonb
WHERE id = 'shock-hemorrhagic' AND tree_id = 'hypotension-workup';

