-- Node: ich-coag-adj (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Hemostatic Adjuncts","body":"**Not on anticoagulation — consider adjunct measures:**\n\n**Tranexamic acid (TXA):**\n• [TXA](#/drug/tranexamic-acid/ich hemostasis) 1 g IV over 10 min (within 3h of onset)\n• Significant reduction in hematoma expansion (OR 0.82)\n• Did NOT improve mortality or functional outcomes in TICH-2\n• May be considered — TICH-3 trial underway\n\n**Antiplatelet agents:**\n• Platelet transfusion is **NOT recommended** (PATCH trial — worse outcomes)\n• [Desmopressin (DDAVP)](#/drug/desmopressin/ich antiplatelet) 0.3 mcg/kg IV may be considered (limited evidence, DASH pilot)\n\n**Thrombocytopenia:**\n• Target platelets >100,000 if possible\n• Transfuse platelets if count <100,000\n\n**Coagulation factors:**\n• Check fibrinogen — supplement with cryoprecipitate if <200 mg/dL\n• Correct any identified coagulopathy","citation":[1,2,6],"next":"ich-bp","treatment":{"firstLine":{"drug":"Tranexamic acid (TXA)","dose":"1 g","route":"IV over 10 min","frequency":"Once","duration":"Single dose","notes":"Give within 3h of onset. Reduces hematoma expansion but no proven mortality benefit (TICH-2)."},"alternative":{"drug":"Desmopressin (DDAVP)","dose":"0.3 mcg/kg","route":"IV","frequency":"Once","duration":"Single dose","notes":"Consider for patients on antiplatelet agents. Limited evidence (DASH pilot). Do NOT transfuse platelets (PATCH trial: worse outcomes)."},"monitoring":"Platelet count (target >100,000). Fibrinogen level (target >200 mg/dL, supplement with cryoprecipitate if low)."},"summary":"Platelets if <100K, cryoprecipitate if fibrinogen <200 — TXA may reduce hematoma expansion","skippable":true}'::jsonb
WHERE id = 'ich-coag-adj' AND tree_id = 'ich';

-- Node: ich-icp-fever (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"ICP, Sodium & Fever","body":"**Intracranial Pressure:**\n• ICP elevation from mass effect, perihematomal edema, and/or obstructive hydrocephalus\n• **Edema peaks at ~5–6 days** — anticipate delayed neurological deterioration\n• Boluses of hypertonic saline or hypertonic bicarbonate for acute ICP crisis (bridge to EVD or surgery)\n• Routine hypertonic saline not supported by evidence\n\n**Sodium:**\n• Avoid hyponatremia or rapid decreases in sodium — worsens cerebral edema\n• Target Na >135 mEq/L\n\n**Fever:**\n• Treat aggressively with [acetaminophen](#/drug/acetaminophen/analgesia) — also provides analgesic benefit\n• **Neurogenic fever** may occur, especially with IVH extension — diagnosis of exclusion\n• Work up infection first (blood/urine cultures, CXR)\n• For refractory neurogenic fever: bromocriptine\n• INTREPID trial: automated surface cooling does NOT improve outcomes — do not use enforced normothermia devices routinely","citation":[1,16],"next":"ich-dvt","summary":"Fever worsens ICH outcomes — target normothermia aggressively with acetaminophen and cooling","safetyLevel":"warning"}'::jsonb
WHERE id = 'ich-icp-fever' AND tree_id = 'ich';

-- Node: ich-dvt (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"DVT Prophylaxis","body":"**AHA/ASA 2022 recommendations:**\n\n**Immediately:**\n• Intermittent pneumatic compression (IPC) — start on admission\n\n**After 24–48 hours:**\n• If ICH has demonstrated stability on serial imaging:\n  – Low-dose [UFH](#/drug/ufh/dvt prophylaxis) 5000 units SQ q8–12h\n  – OR [Enoxaparin](#/drug/enoxaparin/vte prophylaxis) 40 mg SQ daily\n  – Starting chemical DVT prophylaxis is reasonable\n\n**Caution:**\n• Patients with underlying coagulopathy or imaging evidence of ongoing hemorrhage expansion may require individualized approach\n• Weigh bleeding risk vs thromboembolism risk (ICH patients are immobilized, high VTE risk)\n\nHigh-risk for DVT: immobilization, weakness/paralysis, older age, obesity.","citation":[1,2],"next":"ich-disposition","treatment":{"firstLine":{"drug":"Enoxaparin","dose":"40 mg","route":"SQ","frequency":"Daily","duration":"Until ambulatory","notes":"Start after 24-48h if ICH stable on serial imaging. Use IPC immediately on admission."},"alternative":{"drug":"UFH (unfractionated heparin)","dose":"5000 units","route":"SQ","frequency":"q8-12h","duration":"Until ambulatory","notes":"Alternative to enoxaparin. Individualize if coagulopathy or ongoing expansion."},"monitoring":"Serial CT to confirm hemorrhage stability before starting chemical prophylaxis. Monitor for signs of DVT/PE."},"summary":"Start DVT prophylaxis (pneumatic compression) immediately — pharmacologic prophylaxis after 48h if stable"}'::jsonb
WHERE id = 'ich-dvt' AND tree_id = 'ich';

-- Node: mtp-txa (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Tranexamic Acid (TXA)","body":"**Critical timing: Give within 3 hours of injury/onset!** [11]\n\n**CRASH-2 Trial:** TXA given within 3h reduced death from bleeding (4.9% vs 5.7%). Given after 3h, TXA INCREASED mortality (4.4% vs 3.1%). [11]\n\n**Dosing:**\n• [Tranexamic Acid](#/drug/tranexamic-acid/mtp) 1 g IV over 10 min, then 1 g IV over 8 hours (CRASH-2 protocol)\n• **Alternative:** 2 g IV/IO single bolus (no infusion required) — the optimal regimen remains unresolved; the 2025 NAEMSP/ACEP/ACS-COT joint position statement lists both 1 g+1 g and 2 g single-dose as acceptable [26]\n• For PPH: 1 g IV over 10 min (repeat if bleeding continues after 30 min) [8]\n\n**Mechanism:** Inhibits plasmin → prevents clot breakdown (antifibrinolytic)\n\n**Contraindications:**\n• Known hypersensitivity\n• Active thromboembolic disease (relative)\n• DIC with predominant thrombosis (relative)\n\n**Do NOT delay MTP activation to give TXA — give concurrently.**","citation":[8,11,26],"next":"mtp-abo-q","summary":"1g IV 10min then 1g 8hrs — MUST within 3hrs, harmful after","safetyLevel":"critical"}'::jsonb
WHERE id = 'mtp-txa' AND tree_id = 'massive-transfusion';

