-- Node: mcp-red-flags (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Red Flags for Organic Cause","body":"**Organic cause until proven otherwise if ANY present:**\n\n**Historical:**\n• Age >40 with first psychiatric symptoms\n• Acute onset (hours-days vs weeks-months)\n• No prior psychiatric history\n• Recent head trauma\n• Known medical illness (cancer, HIV, thyroid)\n• New medications or recent changes\n\n**Clinical:**\n• Visual hallucinations (vs auditory)\n• Fluctuating consciousness\n• Disorientation (time, place, person)\n• Abnormal vital signs\n• Focal neurologic findings\n• Signs of intoxication/withdrawal","citation":[1,2],"next":"mcp-red-flag-check","summary":"Age >40 first episode, visual hallucinations, fluctuating course, abnormal vitals = organic.","safetyLevel":"critical"}'::jsonb
WHERE id = 'mcp-red-flags' AND tree_id = 'medical-clearance-psych';

-- Node: mcp-first-episode (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"First Psychotic Episode","body":"**First episode requires targeted medical assessment:**\n\n**Labs:**\n• CBC, BMP, glucose\n• TSH when clinically indicated\n• Toxicology screen when substance-induced symptoms are plausible\n• UA if urinary symptoms, pregnancy concern, elderly, or delirium concern\n• RPR/HIV/B12/folate based on risk factors, atypical features, or local protocol\n\n**Imaging:**\n• ED CT for focal deficits, headache/seizure, trauma, delirium features, anticoagulation/immunosuppression, or age >40\n• MRI brain is preferred for stable non-emergent structural evaluation when available\n\n**Consider:**\n• EEG if seizure concern\n• LP if encephalitis concern\n• Anti-NMDA antibodies when young patient has prodrome, seizures, dyskinesias, autonomic instability, or decreased consciousness","citation":[1,5],"next":"mcp-disposition","summary":"First episode: targeted labs; image for neurologic/atypical features or age >40; MRI can be non-emergent if stable."}'::jsonb
WHERE id = 'mcp-first-episode' AND tree_id = 'medical-clearance-psych';

-- Node: ami-resus (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Resuscitation — The 11 As","body":"[The 11 As Checklist](#/info/ami-11as)\n\n**Start immediately while awaiting definitive treatment:**\n\n1. **Aggressive fluids** — LR boluses, blood products PRN\n2. **Address metabolic derangements** — correct acidosis, K+, Mg2+\n3. **Antibiotics** — [Pip-tazo 4.5g IV q6h](#/drug/piperacillin-tazobactam/ami)\n4. **Anticoagulation** — [Heparin](#/drug/ufh/ami) 80 U/kg bolus → 18 U/kg/hr\n5. **Analgesia** — IV opioids (do NOT withhold)\n6. **Avoid vasopressors** — worsen ischemia\n7. **Alleviate distension** — NG tube\n8. **Avoid hyperoxia** — target SpO2 96-99%\n9. **Advance directives** — discuss GOC early\n10. **Abdominal compartment syndrome** — monitor bladder pressures\n11. **All the help** — Vascular, General Surgery, IR, ICU","citation":[2,4,5],"next":"ami-anticoag","summary":"The 11 As: Aggressive fluids, Antibiotics, Anticoagulation, Analgesia, Avoid vasopressors, consults."}'::jsonb
WHERE id = 'ami-resus' AND tree_id = 'mesenteric-ischemia';

-- Node: ami-anticoag (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Anticoagulation — Start Early","body":"**Unfractionated Heparin (preferred):**\n\n• **Bolus:** [Heparin](#/drug/ufh/ami) 80 U/kg IV (max 5000 U)\n• **Infusion:** 18 U/kg/hr\n• **Goal aPTT:** 40-60 seconds\n\n**Why heparin:**\n• Can be rapidly reversed with protamine if surgery needed\n• Early anticoagulation improves survival\n• Prevents clot propagation\n\n🛑 **Do NOT delay anticoagulation waiting for surgery**\n\nStart immediately; it can be reversed if OR needed urgently.","citation":[2,4],"next":"ami-abx","summary":"Heparin 80 U/kg bolus → 18 U/kg/hr, goal aPTT 40-60. Start immediately — can reverse with protamine if needed."}'::jsonb
WHERE id = 'ami-anticoag' AND tree_id = 'mesenteric-ischemia';

-- Node: migraine-mild-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Mild Migraine — Oral Therapy","body":"**Mild migraine may respond to oral medications:**\n\n**First-Line Options:**\n- **NSAIDs:** Ibuprofen 400-800 mg, Naproxen 500-550 mg, Ketorolac 10 mg PO\n- **Acetaminophen:** 1000 mg (if NSAIDs contraindicated)\n- **Triptan:** Sumatriptan 50-100 mg, Rizatriptan 10 mg, Eletriptan 40 mg\n\n**Combination more effective than monotherapy:**\n- Sumatriptan 50-100 mg + Naproxen 500 mg (or fixed-dose sumatriptan 85 mg/naproxen 500 mg tablet — Treximet)\n\n**Antiemetic if nausea:**\n- Ondansetron 4-8 mg ODT\n- Metoclopramide 10 mg PO\n\n**If no improvement in 1-2 hours** → escalate to parenteral therapy.\n\n**Triptan Contraindications:**\n- CAD, prior MI/stroke\n- Uncontrolled hypertension\n- Hemiplegic or basilar migraine\n- MAO inhibitor use within 14 days","citation":[3,4],"next":"migraine-response-check","treatment":{"firstLine":{"drug":"Ibuprofen + Sumatriptan","dose":"Ibuprofen 400-800 mg + Sumatriptan 50-100 mg","route":"PO","frequency":"Once, may repeat sumatriptan x1 after 2h","duration":"Single dose","notes":"Combination therapy more effective than monotherapy"},"alternative":{"drug":"Naproxen","dose":"500-550 mg","route":"PO","frequency":"Once","duration":"Single dose","notes":"May combine with triptan; preferred NSAID for longer duration"},"nsaidAllergy":{"drug":"Acetaminophen + Sumatriptan","dose":"Acetaminophen 1000 mg + Sumatriptan 50-100 mg","route":"PO","frequency":"Once","duration":"Single dose","notes":"Use if NSAIDs contraindicated"},"monitoring":"Reassess in 1-2 hours; escalate to parenteral therapy if no improvement"},"summary":"NSAID + triptan best — triptan CI in CAD/stroke"}'::jsonb
WHERE id = 'migraine-mild-treatment' AND tree_id = 'migraine';

-- Node: migraine-first-line (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Moderate-Severe Migraine — IV Cocktail","body":"**2025 AHS Guidelines — ED First-Line:**\n\n**Standard \"Migraine Cocktail\":**\n\n| Step | Medication | Dose | Notes |\n|------|------------|------|-------|\n| 1 | [Diphenhydramine](#/drug/diphenhydramine/migraine cocktail) | 25-50 mg IV | Give FIRST (prevents akathisia) |\n| 2 | [Prochlorperazine](#/drug/prochlorperazine/migraine cocktail) | 10 mg IV over 15 min | **Level A — Must Offer** (upgraded 2025) |\n| 3 | [Ketorolac](#/drug/ketorolac/migraine) | 15-30 mg IV | 15 mg equally effective as 30 mg |\n| 4 | **NS Bolus** | 500-1000 mL | If dehydrated from vomiting |\n\n⚡ **2025 Update:** Prochlorperazine upgraded to Level A (from Level B). Preferred over metoclopramide when available.\n\n**Before discharge, add:**\n- [Dexamethasone](#/drug/dexamethasone/migraine) 10 mg IV — prevents 48-72h recurrence (NNT=9)\n\n**Key Points:**\n- Slow infusion (15 min) may reduce akathisia risk vs rapid bolus (evidence mixed across trials)\n- Darken the room\n- Give all meds up front (more effective than stepwise)\n- Reassess at 30-60 min [1][3][4]","citation":[1,3,4],"next":"migraine-response-check","treatment":{"firstLine":{"drug":"Diphenhydramine + Prochlorperazine + Ketorolac","dose":"Diphenhydramine 25-50 mg + Prochlorperazine 10 mg + Ketorolac 15-30 mg","route":"IV","frequency":"Once (give all meds together)","duration":"Single dose; infuse prochlorperazine over 15 min","notes":"Give diphenhydramine FIRST to prevent akathisia; 15 mg ketorolac equally effective as 30 mg"},"alternative":{"drug":"Diphenhydramine + Metoclopramide + Ketorolac","dose":"Diphenhydramine 25-50 mg + Metoclopramide 10-20 mg + Ketorolac 15-30 mg","route":"IV","frequency":"Once","duration":"Single dose; infuse metoclopramide slowly","notes":"Second-line per 2025 AHS (Level B); use if prochlorperazine unavailable"},"adjunct":{"drug":"Dexamethasone","dose":"10 mg","route":"IV","frequency":"Once before discharge","duration":"Single dose","notes":"Prevents 48-72h recurrence (NNT=9); give to all patients before discharge"},"monitoring":"Reassess at 30-60 min; monitor for akathisia, dystonia, sedation"},"calculatorLinks":[{"id":"migraine-tx-algo","label":"Treatment Algorithm"}],"summary":"Diphenhydramine FIRST, prochlorperazine 15min + ketorolac"}'::jsonb
WHERE id = 'migraine-first-line' AND tree_id = 'migraine';

-- Node: migraine-status (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Status Migrainosus (>72 hours)","body":"**Status migrainosus = migraine lasting >72 hours**\n\n**Initial Management:**\n- Aggressive IV hydration (1-2L NS)\n- Standard migraine cocktail (prochlorperazine + diphenhydramine + ketorolac)\n- **Dexamethasone 10 mg IV** (reduces recurrence)\n\n**If standard cocktail fails:**\n\n**Dihydroergotamine (DHE) Protocol:**\n- Metoclopramide 10 mg IV (give 30 min before DHE)\n- DHE 1 mg IV over 3 min\n- Can repeat DHE 0.5-1 mg q8h x 24-48h if needed\n- **Contraindicated:** CAD, uncontrolled HTN, pregnancy, recent triptan use\n\n**Alternative:**\n- **Valproate** 500-1000 mg IV (Level C)\n- [Magnesium sulfate](#/drug/magnesium-sulfate/migraine) 1-2 g IV\n\n**Consider admission if:**\n- Refractory to multiple agents\n- Severe dehydration\n- Unable to tolerate PO\n- Need for DHE protocol [1][3]","citation":[1,3],"next":"migraine-response-check","treatment":{"firstLine":{"drug":"Migraine Cocktail + Dexamethasone + IV Fluids","dose":"Diphenhydramine 25-50 mg + Prochlorperazine 10 mg + Ketorolac 15-30 mg + Dexamethasone 10 mg + NS 1-2L","route":"IV","frequency":"Once","duration":"Single dose cocktail; fluids over 1-2 hours","notes":"Aggressive hydration critical in status migrainosus"},"alternative":{"drug":"Dihydroergotamine (DHE) Protocol","dose":"Metoclopramide 10 mg IV (30 min before), then DHE 1 mg IV over 3 min","route":"IV","frequency":"DHE 0.5-1 mg q8h","duration":"24-48 hours (requires admission)","notes":"Contraindicated: CAD, uncontrolled HTN, pregnancy, triptan within 24h"},"adjunct":{"drug":"Magnesium sulfate","dose":"1-2 g","route":"IV","frequency":"Once","duration":"Infuse over 15-30 min","notes":"Especially helpful if migraine with aura"},"monitoring":"Monitor for DHE side effects: nausea, chest tightness, leg cramps; telemetry if DHE protocol"},"summary":"Status >72h: hydration + cocktail + dexa + consider DHE"}'::jsonb
WHERE id = 'migraine-status' AND tree_id = 'migraine';

-- Node: migraine-rescue (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Rescue Therapy Options","body":"**First-line failed — rescue options:**\n\n**Level A (Must Offer):**\n- **Greater Occipital Nerve Block** — highly effective, no systemic side effects\n\n**Level B (Should Offer):**\n- **Sumatriptan SC** 6 mg — if no contraindications\n- **Supraorbital Nerve Block** — alternative to GON\n\n**Level C (May Offer):**\n- **Valproate IV** 500-1000 mg — third-line\n- **Chlorpromazine IV** 12.5 mg — alternative antiemetic\n- [Magnesium sulfate](#/drug/magnesium-sulfate/migraine) 1-2 g IV — especially if aura\n\n**Emerging (Limited Evidence):**\n- [Ketamine](#/drug/ketamine/sub-dissociative analgesia) low-dose IV\n- **Lidocaine** IV infusion\n- **SPG block** (intranasal)\n\n**DO NOT USE:**\n- **Opioids** — Level A against (hydromorphone ineffective)\n- **IV Acetaminophen** — likely ineffective\n\nSelect rescue approach:","citation":[1,3,4],"options":[{"label":"Greater Occipital Nerve Block","description":"Level A recommendation, highly effective","next":"migraine-gon-block"},{"label":"Sumatriptan SC 6 mg","description":"If no vascular contraindications","next":"migraine-triptan-rescue"},{"label":"Valproate IV","description":"Third-line option","next":"migraine-valproate"},{"label":"SPG Block (Intranasal)","description":"Non-invasive nerve block","next":"migraine-spg-block"}],"summary":"GON block Level A, SC triptan B — AVOID opioids"}'::jsonb
WHERE id = 'migraine-rescue' AND tree_id = 'migraine';

-- Node: nf-resus (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Resuscitation — Sepsis Protocol","body":"**NSTI patients are SEPTIC** — apply sepsis bundle: [2][7]\n\n**Immediate actions:**\n1. **IV access** — 2 large-bore IVs or central line\n2. **Fluid resuscitation** — 30 mL/kg LR bolus within 3 hours\n3. **Broad-spectrum antibiotics** — within 1 hour (see next step)\n4. **Labs** — CBC, BMP, lactate, CRP, coags, blood cultures x2, wound cultures\n5. **Mark wound margins** with time\n\n**Vasopressors if needed:**\n• [Norepinephrine](#/drug/norepinephrine/septic vasodilatory shock) 0.05-0.5 mcg/kg/min — first-line\n• Add [Vasopressin](#/drug/vasopressin/septic shock) 0.03-0.04 units/min early\n• Target MAP >=65 mmHg\n\n**Do NOT delay surgery for:**\n• Complete resuscitation\n• Hemodynamic stability\n• Culture results\n• Additional imaging\n\n**The single most important intervention is SURGICAL DEBRIDEMENT.** [2][3]","citation":[2,3,7],"next":"nf-surgery","summary":"Sepsis protocol: 30 mL/kg LR, broad-spectrum abx within 1hr, norepinephrine if needed; do NOT delay surgery for resuscitation","safetyLevel":"critical"}'::jsonb
WHERE id = 'nf-resus' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-fournier (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Fournier Gangrene — Perineal NSTI","body":"**Fournier gangrene** is NSTI of the perineum, scrotum, and genital region. Mortality **40%**. [4][8]\n\n**Risk factors:** [4]\n• Diabetes mellitus (most common)\n• Alcoholism / immunocompromise\n• Urinary tract infection / instrumentation\n• Perianal abscess / anal fissure\n• Recent surgery / trauma\n\n**Key considerations:** [8]\n• **Polymicrobial** — always include broad gram-negative AND anaerobic coverage\n• May require fecal diversion (colostomy)\n• Orchidectomy rarely needed (testes have separate blood supply)\n• Urinary catheter placement (often suprapubic)\n\n**Antibiotic regimen — ensure anaerobic coverage:** [8]\n• [Piperacillin-tazobactam](#/drug/piperacillin-tazobactam/sepsis empiric coverage) 4.5g IV q6h PLUS\n• [Vancomycin](#/drug/vancomycin/sepsis mrsa coverage) 25-30 mg/kg IV load PLUS\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h (toxin suppression)\n\n**Surgical debridement is MANDATORY** — often extensive.","citation":[4,8],"next":"nf-abx-empiric","summary":"Fournier gangrene: perineal NSTI, 40% mortality, polymicrobial; always include broad gram-negative + anaerobic + MRSA coverage; surgical debridement mandatory","safetyLevel":"critical"}'::jsonb
WHERE id = 'nf-fournier' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-head-neck (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Cervical / Head-Neck NSTI","body":"**Cervical necrotizing fasciitis** often originates from: [9]\n• Dental infection (most common)\n• Peritonsillar abscess\n• Ludwig angina\n• Penetrating trauma\n\n**Key considerations:**\n• **Airway compromise** is the primary threat\n• Can rapidly spread to mediastinum (descending necrotizing mediastinitis)\n• CT neck AND chest with contrast\n• Early intubation if airway concern\n• May require awake fiberoptic intubation\n\n**Microbiology:** [9]\n• Typically polymicrobial (oral flora)\n• Streptococci, anaerobes, gram-negatives\n• Mixed oral flora including Fusobacterium, Prevotella\n\n**Antibiotic regimen:** [9]\n• [Piperacillin-tazobactam](#/drug/piperacillin-tazobactam/sepsis empiric coverage) 4.5g IV q6h PLUS\n• [Vancomycin](#/drug/vancomycin/sepsis mrsa coverage) 25-30 mg/kg IV load PLUS\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h\n\n**Consult ENT and CT surgery immediately.**","citation":[9],"next":"nf-abx-empiric","summary":"Head/neck NSTI: airway threat is primary concern; can spread to mediastinum; early intubation; consult ENT and CT surgery; often odontogenic origin","safetyLevel":"critical"}'::jsonb
WHERE id = 'nf-head-neck' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-abx-empiric (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Empiric Antibiotic Therapy","body":"**Triple-drug therapy** covering gram-positives (including MRSA), gram-negatives, and anaerobes: [2][3][10]\n\n[NSTI Treatment Guide](#/info/nf-treatment-guide)\n\n**Recommended Empiric Regimen:**\n\n1. **Broad-spectrum beta-lactam backbone:**\n   • [Piperacillin-tazobactam](#/drug/piperacillin-tazobactam/sepsis empiric coverage) 4.5g IV q6h (preferred) OR\n   • [Meropenem](#/drug/meropenem/sepsis empiric mdr) 1g IV q8h (if resistant organisms suspected)\n\n2. **MRSA Coverage:**\n   • [Linezolid](#/drug/linezolid/necrotizing fasciitis) 600 mg IV q12h (PREFERRED) — superior toxin suppression, avoids nephrotoxicity OR\n   • [Vancomycin](#/drug/vancomycin/sepsis mrsa coverage) 25-30 mg/kg IV load, then 15-20 mg/kg IV q8-12h\n\n3. **Toxin Suppression (add to regimen):**\n   • [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h — inhibits toxin synthesis at ribosomal level [2][3]\n\n**Duration:** 7-14 days total; continue 48-72 hours after final debridement with clinical improvement. [10]","citation":[2,3,10],"next":"nf-special-organisms","summary":"Triple therapy: pip-tazo + linezolid (or vanco) + clindamycin; clindamycin for toxin suppression is critical; 7-14 days total duration","safetyLevel":"critical"}'::jsonb
WHERE id = 'nf-abx-empiric' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-vibrio (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Vibrio vulnificus — Saltwater NSTI","body":"**Vibrio vulnificus** causes rapidly fatal NSTI with **>50% mortality**. [4][11]\n\n**Risk factors:**\n• Liver cirrhosis (100x increased risk)\n• Hemochromatosis\n• Immunocompromise\n• Raw oyster ingestion\n• Saltwater wound exposure (Gulf Coast, warm coastal waters)\n\n**Clinical features:**\n• Extremely rapid progression (hours)\n• Hemorrhagic bullae characteristic\n• Septic shock common at presentation\n• Often requires amputation\n\n**Antibiotic regimen (ADD to empiric therapy):** [4][11]\n• [Doxycycline](#/drug/doxycycline) 100 mg IV q12h PLUS\n• [Ceftriaxone](#/drug/ceftriaxone/community sepsis) 2g IV q24h OR [Ceftazidime](#/drug/ceftazidime) 2g IV q8h\n\n**If already on pip-tazo or carbapenem:**\n• Add doxycycline 100 mg IV q12h (the key agent for Vibrio)\n\n**Surgical debridement URGENT** — mortality increases rapidly with delay.","citation":[4,11],"next":"nf-type-classification","summary":"Vibrio vulnificus: saltwater/oysters, cirrhosis major risk, >50% mortality; add doxycycline + 3rd-gen cephalosporin to standard regimen","safetyLevel":"critical"}'::jsonb
WHERE id = 'nf-vibrio' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-aeromonas (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Aeromonas — Freshwater NSTI","body":"**Aeromonas hydrophila** associated with freshwater exposure. [4]\n\n**Risk factors:**\n• Freshwater injury (lake, river, pond)\n• Immunocompromise\n• Liver disease\n• Leech therapy (medicinal leeches)\n\n**Antibiotic regimen (ADD to empiric therapy):** [4]\n• [Doxycycline](#/drug/doxycycline) 100 mg IV q12h PLUS\n• [Ciprofloxacin](#/drug/ciprofloxacin) 400 mg IV q12h OR [Levofloxacin](#/drug/levofloxacin/necrotizing soft tissue infection) 750 mg IV q24h\n\n**If already on pip-tazo or carbapenem:**\n• Add doxycycline 100 mg IV q12h + fluoroquinolone\n\n**Note:** Aeromonas is often resistant to ampicillin and first-generation cephalosporins.","citation":[4],"next":"nf-type-classification","summary":"Aeromonas: freshwater exposure, leech therapy; add doxycycline + fluoroquinolone to standard regimen; resistant to ampicillin"}'::jsonb
WHERE id = 'nf-aeromonas' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-toxin (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Toxin Suppression — Clindamycin","body":"**Clindamycin is CRITICAL for toxin-mediated disease:** [2][3]\n\n**Mechanism:** [3]\n• Inhibits bacterial protein synthesis at 50S ribosome\n• Suppresses exotoxin production (superantigens, streptolysins)\n• Effect persists even as bacteria die\n• Beta-lactams may paradoxically INCREASE toxin release (Eagle effect)\n\n**Dosing:** [2]\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h\n• Some experts recommend **1200 mg IV q6h** for severe TSS [2]\n\n**When to use:**\n• ALL suspected or confirmed NSTI\n• Especially important for:\n  - Group A Streptococcus (GAS)\n  - Toxic shock syndrome\n  - Clostridial infection\n\n**Continue clindamycin** throughout antibiotic course in toxin-producing infections.\n\n**Dual toxin suppression:** [2]\n• For critically ill patients with streptococcal TSS, consider:\n  - [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h PLUS\n  - [Linezolid](#/drug/linezolid/necrotizing fasciitis) 600 mg IV q12h\n• They act at different ribosomal sites and may be synergistic","citation":[2,3],"next":"nf-ivig","summary":"Clindamycin 900 mg IV q8h CRITICAL for toxin suppression; beta-lactams may increase toxin release (Eagle effect); consider dual suppression with linezolid in severe TSS"}'::jsonb
WHERE id = 'nf-toxin' AND tree_id = 'necrotizing-fasciitis';

-- Node: nf-abx-deescalation (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Antibiotic De-escalation","body":"**De-escalate antibiotics based on culture results:** [10]\n\n**When cultures are final (typically 48-72 hours):**\n\n**If Group A Streptococcus (GAS):**\n• [Penicillin G](#/drug/penicillin-g-iv) 4 million units IV q4h PLUS\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h (continue for toxin suppression)\n\n**If MRSA:**\n• [Vancomycin](#/drug/vancomycin/sepsis mrsa coverage) OR [Linezolid](#/drug/linezolid/necrotizing fasciitis) PLUS\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) if toxin-producing\n\n**If Clostridial:**\n• [Penicillin G](#/drug/penicillin-g-iv) 4 million units IV q4h PLUS\n• [Clindamycin](#/drug/clindamycin/necrotizing fasciitis) 900 mg IV q8h\n\n**Total duration:** [10]\n• 7-14 days total\n• Continue IV therapy 48-72 hours after final debridement\n• Transition to PO when stable and tolerating oral intake\n\n**ID consultation** recommended for complex cases or resistant organisms.","citation":[10],"next":"nf-dispo","summary":"De-escalate at 48-72h based on cultures; GAS: penicillin + clindamycin; MRSA: vanco/linezolid + clindamycin; 7-14 days total"}'::jsonb
WHERE id = 'nf-abx-deescalation' AND tree_id = 'necrotizing-fasciitis';

-- Node: nstemi-post-pci (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Post-PCI P2Y12 Selection","body":"Select P2Y12 inhibitor for 12-month DAPT.\nSee [P2Y12 Selection Guide](#/info/nstemi-antiplatelet-cx)\n\n**Preferred:** [Ticagrelor](#/drug/ticagrelor) 90 mg BID\n• PLATO trial: reduced CV death/MI/stroke vs clopidogrel (NNT 54)\n• Aspirin ≤100 mg/day required\n\n**High ischemic risk (diabetes, stent thrombosis):** [Prasugrel](#/drug/prasugrel) 10 mg daily\n• TRITON-TIMI 38: more potent, but more bleeding\n• CONTRAINDICATED if prior stroke/TIA\n• Avoid if age ≥75 or weight <60 kg\n\n**High bleeding risk or on OAC:** [Clopidogrel](#/drug/clopidogrel/acs) 75 mg daily\n• Preferred for triple therapy (OAC + DAPT)\n• Least bleeding risk of the three","citation":[1,6,7],"options":[{"label":"Ticagrelor selected (standard)","next":"nstemi-dapt-duration"},{"label":"Prasugrel selected (high ischemic risk)","next":"nstemi-dapt-duration"},{"label":"Clopidogrel selected (high bleeding risk / OAC)","next":"nstemi-dapt-duration"},{"label":"CABG indicated (anatomy)","next":"nstemi-cabg"}],"treatment":{"firstLine":{"drug":"Ticagrelor","dose":"90 mg","route":"PO","frequency":"Twice daily (BID)","duration":"12 months","notes":"Preferred P2Y12 for most patients (PLATO: NNT 54). Aspirin must be ≤100 mg/day. May cause dyspnea."},"alternative":{"drug":"Clopidogrel","dose":"75 mg","route":"PO","frequency":"Once daily","duration":"12 months","notes":"Use for high bleeding risk or patients on OAC. Preferred for triple therapy."},"monitoring":"Monitor for bleeding (GI, bruising, epistaxis). Assess medication adherence. Do NOT discontinue without cardiology guidance."},"summary":"P2Y12 for 12mo DAPT: ticagrelor preferred (aspirin ≤100mg), prasugrel if high ischemic risk (CI if prior stroke), clopidogrel if on OAC","safetyLevel":"warning"}'::jsonb
WHERE id = 'nstemi-post-pci' AND tree_id = 'nstemi';

-- Node: nstemi-discharge (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Discharge Medications","body":"**The 5 pillars of post-ACS pharmacotherapy:**\n\n1. **DAPT:** Aspirin 81 mg + P2Y12 inhibitor × 12 months\n2. **Statin:** [Atorvastatin](#/drug/atorvastatin) 80 mg (or rosuvastatin 20–40 mg) — target LDL <70\n3. **Beta-blocker:** [Metoprolol](#/drug/metoprolol/acs) succinate — continue if EF <40% or hypertension; may discontinue after 1 year if EF preserved\n4. **ACE inhibitor/ARB:** Start within 24h if EF ≤40%, hypertension, or diabetes. Consider for all post-ACS patients.\n5. **Aldosterone antagonist:** Add if EF ≤40% + HF symptoms or diabetes (EPHESUS trial)\n\nAlso: PPI if DAPT (GI prophylaxis — use pantoprazole, NOT omeprazole with clopidogrel)","citation":[1,2],"next":"nstemi-risk-factors","treatment":{"firstLine":{"drug":"Lisinopril (or equivalent ACE inhibitor)","dose":"2.5-5 mg, titrate to 10-40 mg","route":"PO","frequency":"Once daily","duration":"Indefinite","notes":"Start within 24h if EF ≤40%, hypertension, or diabetes. Consider for all ACS patients. ARNI (sacubitril/valsartan) if EF ≤40% and stable."},"alternative":{"drug":"Losartan (or equivalent ARB)","dose":"25-50 mg, titrate to 100 mg","route":"PO","frequency":"Once daily","duration":"Indefinite","notes":"Use if ACE inhibitor intolerant (cough). Note: VALIANT studied valsartan (not losartan) and showed valsartan non-inferior to captopril post-MI; losartan-specific post-MI data (OPTIMAAL) showed a non-significant trend favoring captopril, not established equivalence."},"monitoring":"Cr and K+ 1-2 weeks after initiation/titration. Monitor for hypotension, hyperkalemia, cough (ACEi)."},"summary":"Five pillars post-ACS: DAPT, high-intensity statin, beta-blocker, ACEi/ARB, aldosterone antagonist if EF≤40%; PPI with DAPT (not omeprazole)"}'::jsonb
WHERE id = 'nstemi-discharge' AND tree_id = 'nstemi';

-- Node: pe-crashing (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Crashing PE — Category D-E","body":"**Category E:** Cardiopulmonary failure — sustained SBP <90 or ≥40 mmHg drop for >15 min, cardiogenic shock, cardiac arrest.\n\n**Category D:** Pre-failure — transient/borderline hypotension, approaching deterioration, HR <40.\n\n**Mortality >15%** without immediate reperfusion.\n\n**Red flags:**\n• **Bradycardia (HR <40)** — most ominous, harbinger of brady-asystolic arrest\n• Lactate >2 mM — 10% absolute mortality increase, HR 12 for death\n• RV dilatation on echo/CT\n\n**ICD-10:** I26.02 (saddle PE with cor pulmonale), I26.09, I26.99","citation":[1,6],"next":"pe-crashing-resus","images":[{"src":"images/pe-treatment/saddle-pe-ct.png","alt":"CT pulmonary angiogram showing saddle embolus straddling the main pulmonary artery bifurcation with bilateral filling defects","caption":"Saddle PE on CT-PA — massive embolus at the main PA bifurcation with bilateral filling defects. (CC BY-SA 3.0, James Heilman MD)"}],"summary":"Category E = shock/arrest; Category D = pre-arrest (HR <40 = ominous); lactate >2 mM = 10% mortality increase","safetyLevel":"critical"}'::jsonb
WHERE id = 'pe-crashing' AND tree_id = 'pe-treatment';

-- Node: pe-crashing-reperfusion (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":2,"title":"Reperfusion Strategy","body":"**Anticoagulation** — start immediately:\n• [UFH](#/drug/ufh/pe) — no bolus if thrombolysis imminent; low-dose infusion ≤500 U/hr\n• UFH preferred (can be stopped if hemorrhage)\n\n**Systemic thrombolysis** — only intervention with mortality benefit data (foundational massive/submassive PE management).\n\n**Dosing options:**\n• Standard: [Alteplase](#/drug/alteplase/pulmonary) **100 mg IV over 2h** (0.6 mg/kg up to 50 mg over first 15 min, remainder over next 1h45min)\n• Reduced-dose: **50 mg IV** over 2h (emerging — less bleeding, equivalent efficacy; HI-PEITHO 2026)\n• Cardiac arrest: **50 mg IV bolus** + sustained CPR\n• **Tenecteplase (alternative, off-label):** weight-based single bolus — 30 mg (<60 kg), 35 mg (60–69), 40 mg (70–79), 45 mg (80–89), 50 mg (≥90 kg). Single bolus advantage; mortality similar to alteplase.\n\n**2026 update:** Mechanical thrombectomy now preferred over CDT for stable-enough patients (PEERLESS-I trial). STRATIFY (2026) shows peripheral 20 mg tPA over 6h equivalent to CDT.","citation":[1,2,3,6,7,8,11,12],"options":[{"label":"Systemic Thrombolysis","description":"No absolute contraindications — proceed with alteplase","next":"pe-anticoag-selection"},{"label":"Thrombolysis Contraindicated","description":"Recent surgery, active bleeding, prior ICH, etc.","next":"pe-advanced-interventions","urgency":"urgent"},{"label":"Refractory Shock / Arrest","description":"Failed thrombolysis or deteriorating despite treatment","next":"pe-advanced-interventions","urgency":"critical"}],"treatment":{"firstLine":{"drug":"Alteplase","dose":"100 mg (or 50 mg reduced-dose; 50 mg IV push if cardiac arrest)","route":"IV","frequency":"Over 2 hours (0.6 mg/kg up to 50 mg over first 15 min, remainder over next 1h45min); flat 50 mg IV push if cardiac arrest","duration":"Single dose","notes":"Cardiac arrest: 50 mg IV bolus + CPR; avoid concurrent heparin bolus. Tenecteplase alternative: weight-based 30–50 mg single bolus."},"alternative":{"drug":"UFH (low-dose)","dose":"≤500 units/hr infusion (no bolus)","route":"IV","frequency":"Continuous","duration":"Until reperfusion achieved","notes":"Give alteplase BEFORE heparin to reduce bleeding risk"},"monitoring":"Hemodynamics; fibrinogen if reduced-dose protocol; bleeding signs"},"calculatorLinks":[{"id":"alteplase-pe-dosing","label":"Alteplase Dosing"}],"summary":"UFH (no bolus) + alteplase 100 mg over 2h (or 50 mg reduced-dose); cardiac arrest = 50 mg bolus + CPR","safetyLevel":"critical"}'::jsonb
WHERE id = 'pe-crashing-reperfusion' AND tree_id = 'pe-treatment';

-- Node: pe-cdt (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Catheter-Directed Thrombolysis","body":"**Low-dose alteplase delivered directly to clot** via catheter.\n\n**Typical protocol:**\n• Alteplase 1-2 mg/hr per catheter (total 8-24 mg over 6-24h)\n• With or without ultrasound assistance (EKOS)\n\n**Key insight (STRATIFY):**\n• Peripheral slow infusion achieves equivalent outcomes to catheter-directed\n• Avoids procedural risk and cost\n• Option: 20 mg alteplase IV over 6h with fibrinogen monitoring\n\n**Bleeding risk:** 0.13% ICH in CDT trials (much lower than systemic full-dose)","citation":[7,9,12],"next":"pe-anticoag-selection","summary":"Alteplase 8-24 mg over 6-24h via catheter; peripheral slow infusion (20 mg over 6h, STRATIFY) may be equivalent"}'::jsonb
WHERE id = 'pe-cdt' AND tree_id = 'pe-treatment';

-- Node: rosc-pressors (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Vasopressor Support","body":"**Vasopressor support:**\n• First-line: [Norepinephrine](#/drug/norepinephrine/post cardiac arrest) 0.1-0.5 mcg/kg/min\n• Refractory: add [Vasopressin](#/drug/vasopressin/post cardiac arrest) 0.04 units/min\n• If cardiac dysfunction: [Dobutamine](#/drug/dobutamine/cardiogenic shock) 2-20 mcg/kg/min or [Milrinone](#/drug/milrinone/cardiogenic shock)\n• Echo to assess LV function — post-arrest myocardial stunning is common and usually recovers in 24-72h\n\n**Avoid epinephrine infusion** post-ROSC if possible (tachyarrhythmias, myocardial oxygen demand).","citation":[1,5,6],"next":"rosc-ttm-check","summary":"Norepinephrine first-line, add vasopressin if refractory, dobutamine for cardiac dysfunction"}'::jsonb
WHERE id = 'rosc-pressors' AND tree_id = 'post-rosc';

-- Node: rosc-seizure (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Post-Arrest Seizures","body":"**Post-arrest seizures** occur in 20-30% of comatose survivors.\n\n• Continuous EEG monitoring recommended for all comatose post-arrest patients\n• Clinical seizures may be subtle (eye twitching, nystagmus) or masked by paralysis\n• Treatment: [Levetiracetam](#/drug/levetiracetam/status epilepticus) 60 mg/kg IV (max 4500mg) — first-line\n• Refractory: valproate, phenobarbital, midazolam/propofol infusion\n• **Myoclonus ≠ seizure** — Lance-Adams syndrome (post-hypoxic myoclonus) has better prognosis than true status epilepticus","citation":[5,6,8],"next":"rosc-icu-targets","summary":"20-30% have post-arrest seizures — continuous EEG, levetiracetam first-line, myoclonus is not always seizure","safetyLevel":"warning"}'::jsonb
WHERE id = 'rosc-seizure' AND tree_id = 'post-rosc';

-- Node: k-hyper-step3 (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Step 3: Kaliuresis (Diuretic Strategy)","body":"Scale diuretic intensity to severity of hyperkalemia and renal function.\n\n**Normal renal function:**\n• [Furosemide](#/drug/furosemide/hyperkalemia) 40-80 mg IV alone may suffice\n\n**Moderate-severe renal dysfunction (\"nephron bomb\"):**\n• [Furosemide](#/drug/furosemide/hyperkalemia) 160-250 mg IV (or [Bumetanide](#/drug/bumetanide) 4-5 mg IV)\n• + [Chlorothiazide](#/drug/chlorothiazide) 500-1000 mg IV (or [Metolazone](#/drug/metolazone) 5-10 mg PO)\n• +/- [Acetazolamide](#/drug/acetazolamide) 250-1000 mg IV/PO\n• +/- [Fludrocortisone](#/drug/fludrocortisone/hyperkalemia) 0.2 mg PO (esp. patients on ACEi/ARB, tacrolimus)\n\n**Replace urine losses** with crystalloid:\n• Bicarb < 22 → isotonic bicarbonate\n• Bicarb ≥ 22 → Lactated Ringers\n\nIn life-threatening hyperK, **err on the side of excessive diuretic**. Large-volume diuresis is easily corrected with crystalloid.","citation":[1,2],"next":"k-hyper-step3-response","treatment":{"firstLine":{"drug":"Furosemide + Chlorothiazide (Nephron Bomb)","dose":"Furosemide 160-250 mg IV + Chlorothiazide 500-1000 mg IV","route":"IV","frequency":"Once, may repeat","duration":"Until adequate urine output and K+ improving","notes":"For moderate-severe renal dysfunction. Add Acetazolamide 250-1000 mg and/or Fludrocortisone 0.2 mg PO PRN."},"alternative":{"drug":"Furosemide (monotherapy)","dose":"40-80 mg","route":"IV","frequency":"Once, may repeat","duration":"Until adequate urine output and K+ improving","notes":"May suffice alone with normal renal function"},"monitoring":"Urine output, replace losses with LR (bicarb >22) or isotonic bicarb (bicarb <22). Check K+, Mg frequently."},"summary":"Scale diuretic to renal function — \"nephron bomb\" for moderate-severe CKD, replace urine losses with crystalloid"}'::jsonb
WHERE id = 'k-hyper-step3' AND tree_id = 'potassium';

-- Node: k-hypopp-assess (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":6,"title":"Periodic Paralysis Assessment","body":"**Hypokalemic Periodic Paralysis (HypoPP)**\n\nEpisodic flaccid paralysis, **proximal > distal**, with normal-to-decreased reflexes. Lasting minutes to days with spontaneous recovery.\n\n**Triggers:** Rest after strenuous exercise, carbohydrate-rich evening meals (morning attacks), stress, cold, high sodium intake, corticosteroids, alcohol\n\n**KEY DISTINCTION:** Hypokalemia in HypoPP is **transcellular redistribution, NOT true body K+ depletion**. This fundamentally changes treatment.\n\n**Genetics:** CACNA1S (calcium channel) or SCN4A (sodium channel) mutations.","citation":[17,18],"options":[{"label":"Confirmed/Suspected HypoPP — Treat Attack","description":"Episodic weakness with triggers, family history, or prior episodes","next":"k-hypopp-acute"},{"label":"Not Periodic Paralysis","description":"Proceed to standard hypokalemia management","next":"k-hypo-severe"}],"summary":"Episodic flaccid paralysis with triggers — transcellular redistribution, NOT true depletion"}'::jsonb
WHERE id = 'k-hypopp-assess' AND tree_id = 'potassium';

-- Node: k-hypopp-prevent (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"HypoPP: Prevention & Long-Term","body":"**Long-term prevention of hypokalemic periodic paralysis attacks.**\n\nTrigger avoidance: low sodium, low carbohydrate diet, avoid steroids/cold/stress/alcohol.\n\nDaily oral KCl 10-20 mEq TID (especially nocturnal dose for morning attacks).\n\nAcetazolamide is first-line pharmacologic prevention. If intolerant: K-sparing diuretics (triamterene, spironolactone, eplerenone).\n\nGenetic counseling: CACNA1S or SCN4A testing for family planning.","citation":[17,18],"recommendation":"Trigger avoidance: low sodium, low carbohydrate diet, avoid steroids/cold/stress/alcohol. Daily oral KCl 10-20 mEq TID (especially nocturnal dose for morning attacks). Acetazolamide is first-line pharmacologic prevention (mechanism uncertain — may involve systemic acidosis reducing attack susceptibility). If intolerant: K-sparing diuretics (triamterene, spironolactone, eplerenone). Magnesium supplementation may enhance renal K+ retention. Anesthetic precautions: strict K+ control, avoid glucose/salt loads, maintain temperature and acid-base balance. Genetic counseling: CACNA1S or SCN4A testing for family planning."}'::jsonb
WHERE id = 'k-hypopp-prevent' AND tree_id = 'potassium';

-- Node: pph-tissue (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Tissue — Retained Products","body":"**RETAINED PLACENTA / PRODUCTS OF CONCEPTION**\n\n**CLINICAL CLUES**\n• Placenta appears incomplete on inspection (missing cotyledon, torn edge, ragged membranes)\n• Firm uterus but persistent bleeding\n• Placenta not delivered within 30 minutes postpartum (retained placenta by definition)\n• Bedside ultrasound: echogenic material in the uterine cavity\n\n**MANAGEMENT**\n\n**1. MANUAL EXTRACTION / EXPLORATION**\n• Adequate analgesia — regional, procedural sedation, or general anesthesia\n• Insert a gloved hand into the uterus, sweep with fingers to detach adherent placenta or fragments\n• **Stop if you encounter a plane of cleavage resistance** — suspect [placenta accreta spectrum](#/info/pph-accreta)\n• Broad-spectrum antibiotics (ampicillin + gentamicin or cefoxitin)\n\n**2. CURETTAGE (if needed)** — in OR with ultrasound guidance, blunt curette preferred over sharp\n\n**3. IF ACCRETA / INCRETA / PERCRETA SUSPECTED**\n• **DO NOT force separation** — catastrophic hemorrhage\n• Leave placenta in situ, resuscitate, transfer to OR for controlled delivery and likely hysterectomy\n• Risk factors: prior C-section (especially multiple), prior uterine surgery, placenta previa overlying scar, advanced maternal age\n\n**4. SECONDARY (LATE) PPH** — retained products are the most common cause of hemorrhage 24 hours to 12 weeks postpartum; treat with [methylergonovine](#/drug/methylergonovine/postpartum hemorrhage), antibiotics, and consider D&C with ultrasound guidance. [1][13]","citation":[1,13],"next":"pph-bleeding-check","images":[{"src":"images/pph/placenta-accreta.png","alt":"Side-by-side diagram of a uterus showing three types of abnormal placental invasion — accreta (attached to myometrium), increta (into myometrium), and percreta (through serosa)","caption":"Placenta accreta spectrum: accreta (attached to myometrium) → increta (invades into myometrium) → percreta (penetrates serosa and can invade adjacent organs). (Wikimedia Commons — Public Domain.)"}],"summary":"Explore uterus manually — stop if resistance (accreta). Ultrasound-guided D&C if needed."}'::jsonb
WHERE id = 'pph-tissue' AND tree_id = 'pph';

-- Node: pph-oxytocin (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Oxytocin (Pitocin) — First Line","body":"**[Oxytocin (Pitocin)](#/drug/oxytocin/postpartum hemorrhage)** — first-line uterotonic in every PPH.\n\n**DOSE**\n• **20 units in 1 L NS or LR — infuse at 250 mL/hr** (≈83 mU/min)\n• Alternative if no IV access: **10 units IM**\n• **NEVER give IV push** — causes profound hypotension and can trigger cardiac arrest\n\n**MAX** 40 units / 500 mL (higher concentrations trigger hypotension)\n\n**CAUTIONS**\n• Water intoxication with prolonged high-dose infusion (antidiuretic effect)\n• Hypotension with rapid bolus\n\n**ASSESS IN 5-10 MINUTES**\n• Uterus firm? → Continue infusion, monitor\n• Still boggy / still bleeding → **escalate to Methylergonovine** [1][8]","citation":[1,8],"next":"pph-methergine-check","treatment":{"firstLine":{"drug":"Oxytocin","dose":"20 units in 1L NS or LR","route":"IV infusion","frequency":"250 mL/hr (~83 mU/min)","duration":"Until uterine tone maintained","notes":"Never IV push — causes profound hypotension. Alternative: 10 units IM if no IV."},"monitoring":"Uterine tone every 5 min, vital signs, urine output. If still boggy at 5-10 min → escalate."},"summary":"20u in 1L NS at 250 mL/hr (or 10u IM). NEVER IV push. Reassess in 5-10 min."}'::jsonb
WHERE id = 'pph-oxytocin' AND tree_id = 'pph';

-- Node: rhabdo-hyperkalemia-tx (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Hyperkalemia Management","body":"**Life-threatening hyperkalemia requires immediate treatment:**\n\n**Cardiac membrane stabilization:**\n• [Calcium gluconate](#/drug/calcium-gluconate/hyperkalemia) 1-2 g IV over 2-3 min (preferred) OR\n• [Calcium chloride](#/drug/calcium-chloride/hyperkalemia) 500-1000 mg IV (central line preferred)\n\n**Potassium shifting:**\n• [Regular insulin](#/drug/regular-insulin/hyperkalemia) 5 units IV + [D50W](#/drug/dextrose/hyperkalemia) 50-100 mL (1-2 amps)\n• [Albuterol](#/drug/albuterol-neb/hyperkalemia) 10-20 mg nebulized\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/hyperkalemia) 50-100 mEq IV (if acidotic)\n\n**Potassium elimination:**\n• [Furosemide](#/drug/furosemide/hyperkalemia) 40-80 mg IV (if adequate urine output)\n• Dialysis for refractory cases or AKI\n\n**Continuous cardiac monitoring. Recheck K in 1-2 hours.**\n\nSee [Potassium Disorders](#/tree/potassium) for complete management.","citation":[1,6],"recommendation":"Treat hyperkalemia immediately with calcium, insulin/glucose, albuterol. Consider dialysis if refractory or anuric.","treatment":{"firstLine":{"drug":"Calcium gluconate","dose":"1-2 g (10-20 mL of 10%)","route":"IV","frequency":"Over 2-3 min, may repeat","duration":"As needed for cardiac protection","notes":"Cardiac membrane stabilization. Does NOT lower K."},"alternative":{"drug":"Regular insulin + D50W","dose":"Insulin 5 units IV + D50W 50-100 mL (1-2 amps)","route":"IV","frequency":"Once, may repeat","duration":"Effect lasts 4-6 hours","notes":"Shifts K intracellularly. Monitor glucose q1h. 5 units (not 10) reduces hypoglycemia risk with similar K-lowering effect."},"monitoring":"Continuous cardiac monitor. Recheck K in 1-2 hours. Glucose q1h after insulin."},"confidence":"definitive"}'::jsonb
WHERE id = 'rhabdo-hyperkalemia-tx' AND tree_id = 'rhabdomyolysis';

