-- Node: sepsis-fluids (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"IV Fluid Resuscitation","body":"**30 mL/kg IV crystalloid** — start within 1 hour, complete within 3 hours [2][24]\n\n**Fluid choice:** Balanced crystalloid preferred (Lactated Ringer''s) [24]\n• SMART trial: lower composite of death, new RRT, and persistent renal dysfunction vs 0.9% NaCl [24]\n• **Avoid HES** — 6S trial: increased mortality (51 vs 43%) and RRT (22 vs 16%) [10]\n• **No benefit to albumin** vs crystalloid (SAFE trial) [24]\n\n**Administration:** Boluses of 500 mL, reassess between each [24]\n• Stop if pulmonary edema develops or no further response\n• CLOVERS trial: restrictive vs liberal fluid strategy for sepsis-induced hypotension showed no significant difference in 90-day mortality [8]\n\n**Special populations:**\n• **Obesity (BMI >30):** Use ideal body weight for calculation [24]\n• **Heart failure / ESRD:** Smaller initial bolus acceptable — CMS allows <30 mL/kg if documented [24]\n• **Pneumonia with mild hypotension:** Fluid-conservative approach + early vasopressors may be better [23]\n\n**After initial resuscitation:** Restrict further fluids — most IV crystalloid extravasates (~95% leaves vasculature). [23]\n\n[Fluid Resuscitation Guide](#/info/sepsis-fluid-guide)","citation":[2,8,9,10,23,24],"next":"sepsis-abx-empiric","treatment":{"firstLine":{"drug":"Lactated Ringer''s","dose":"30 mL/kg","route":"IV","frequency":"500 mL boluses","duration":"within 3 hours","notes":"Balanced crystalloid preferred per SMART trial"},"alternative":{"drug":"0.9% NaCl","dose":"30 mL/kg","route":"IV","frequency":"500 mL boluses","duration":"within 3 hours","notes":"Use if LR unavailable. Avoid HES (increased mortality)."},"monitoring":"Reassess between boluses. Stop if pulmonary edema develops. Use IBW for obese patients."},"summary":"30 mL/kg LR within 3hr in 500mL boluses — avoid HES (increased mortality); restrict fluids after initial resuscitation"}'::jsonb
WHERE id = 'sepsis-fluids' AND tree_id = 'sepsis';

-- Node: sepsis-map-target (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"MAP Targets & Personalization","body":"**Default MAP target:** ≥65 mmHg (SSC 2021) [2]\n\n**Personalized targets:** [23]\n• **Chronic hypertension:** Consider MAP 80-85 mmHg (SEPSISPAM: improved renal outcomes but more AF) [19]\n• **Younger / previously normotensive:** MAP 60-65 may be sufficient (65-Trial) [18]\n• **Elevated CVP or IAP:** Higher MAP may be needed to maintain organ perfusion gradient [23]\n\n**Capillary Refill Time (CRT)** — emerging perfusion target: [16][17]\n• Normal CRT <3 seconds suggests adequate perfusion\n• ANDROMEDA-SHOCK: CRT-guided resuscitation ≥ lactate-guided (improved SOFA at 72h) [16]\n• ANDROMEDA-SHOCK-2 (n=1467): CRT-targeted resuscitation superior on hierarchical composite outcome (win ratio 1.16) — shorter vital organ support duration (-1.31 days) and ICU stay, with no difference in 28-day mortality [17]\n\n**Vasopressor reduction challenge** (IBCC approach): [23]\n• If on dual vasopressors (NE + vasopressin), consider down-titrating to assess for excessive vasoconstriction\n• Target MAP 60-70 for 1 hour → reassess perfusion\n• Systolic HF patients may benefit from reduced afterload","citation":[2,16,17,18,19,23],"next":"sepsis-fluid-assess","summary":"Default MAP >=65; personalize for chronic HTN (80-85) or normotensive elderly (60-65); CRT <3sec emerging target","skippable":true}'::jsonb
WHERE id = 'sepsis-map-target' AND tree_id = 'sepsis';

-- Node: sepsis-steroids (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Corticosteroid Therapy","body":"**For patients on vasopressors for septic shock:** [2][14][15]\n\n**[Hydrocortisone](#/drug/hydrocortisone/septic shock)** 50 mg IV q6h OR 200 mg/day continuous infusion [2]\n\n**Evidence:**\n• **ADRENAL trial** (n=3800): Steroids reduce time on vasopressors, ICU LOS, and duration of intubation. No increase in superinfection. [14]\n• **APROCCHSS trial** (n=1241): Hydrocortisone + [Fludrocortisone](#/drug/fludrocortisone/septic shock) 50 mcg PO daily × 7 days reduced 90-day mortality (43% vs 49.1%) [15]\n• Meta-analyses confirm: shorter shock duration, earlier vasopressor weaning. Mortality benefit debated but possible if started early in sickest patients. [14][15]\n\n**Risks:**\n• Hyperglycemia (monitor and treat)\n• Steroid myopathy risk in paralyzed patients\n• No increased superinfection risk (debunked by ADRENAL) [14]\n\n**Timing:** Consider early initiation — antibiotics can trigger Jarisch-Herxheimer reaction; front-loaded steroids may blunt this. [23]\n\n**Taper:** When vasopressors discontinued, taper over 2-3 days (do not stop abruptly).","citation":[2,14,15,23],"next":"sepsis-cardiomyop","treatment":{"firstLine":{"drug":"Hydrocortisone","dose":"50 mg","route":"IV","frequency":"q6h","duration":"until off vasopressors, then taper","notes":"OR 200 mg/day continuous infusion"},"alternative":{"drug":"Fludrocortisone","dose":"50 mcg","route":"PO","frequency":"daily","duration":"7 days","notes":"Add to hydrocortisone per APROCCHSS protocol"},"monitoring":"Monitor glucose. Taper over 2-3 days when vasopressors discontinued."},"summary":"Hydrocortisone 50mg IV q6h for vasopressor-dependent shock — reduces shock duration; taper over 2-3 days when off pressors"}'::jsonb
WHERE id = 'sepsis-steroids' AND tree_id = 'sepsis';

