-- Node: scd-priapism-route (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":1,"title":"Priapism in SCD","body":"**Priapism** affects ~40% of males with SCD. [1]\n\nIntervention should occur within **4 hours** of erection duration to prevent permanent scarring and erectile dysfunction.\n\n**Initial Management:**\n• IV hydration\n• Analgesia (per VOC pathway)\n• Supplemental oxygen\n• Oral pseudoephedrine 30–60 mg may be considered [1]\n• Ketamine at procedural sedation doses has been shown to assist with corporal detumescence [1]\n\n**Definitive Management:**\n[Priapism Management](#/tree/priapism) — full aspiration, irrigation, and phenylephrine injection protocol\n\nEmergent urology consultation for definitive management.","citation":[1],"recommendation":"Initiate IV hydration, analgesia, and O2. If >4 hours duration, proceed to corporal aspiration per Priapism consult. Emergent urology consultation.","treatment":{"firstLine":{"drug":"Pseudoephedrine","dose":"30-60 mg","route":"PO","frequency":"Once","duration":"Single dose","notes":"May assist with detumescence; use while preparing for procedural intervention"},"alternative":{"drug":"Ketamine","dose":"1-2 mg/kg","route":"IV","frequency":"Once","duration":"Procedural sedation dose","notes":"Has been shown to assist with corporal detumescence"},"monitoring":"Monitor for resolution of erection; if >4 hours, proceed to corporal aspiration with phenylephrine"},"confidence":"recommended"}'::jsonb
WHERE id = 'scd-priapism-route' AND tree_id = 'sickle-cell';

-- Node: scd-voc-iv (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"IV Analgesia & Fluids","body":"**NSAID (administer with first opioid dose):**\n[Ketorolac](#/drug/ketorolac/scd pain crisis) 0.5 mg/kg IV\n• Max 15 mg if <16 years, max 30 mg if ≥16 years\n• Reduces opioid requirements [8]\n• **Contraindications:** pregnancy, renal impairment, ketorolac within 5 days, ibuprofen within 6 hours, bleeding concerns, history of renal impairment\n\n**Opioid (choose one based on patient preference/pain plan):**\n[Morphine](#/drug/morphine/scd pain crisis) 0.1–0.2 mg/kg IV (max 8 mg)\nOR\n[Hydromorphone](#/drug/hydromorphone/scd pain crisis) 0.015–0.02 mg/kg IV (max 1 mg)\nOR\n[Fentanyl](#/drug/fentanyl/scd pain crisis iv) 2 mcg/kg IV (max 100 mcg)\n\nIf unable to obtain IV: Oxycodone 0.1 mg/kg PO (max 10 mg)\n\n**IV Fluids:**\n• NS 10 mL/kg bolus (max 1L) over 60 minutes\n• If concern for dehydration: 20 mL/kg bolus (max 1L)\n• Then start 1× maintenance IVF\n• **Avoid overhydration** — can worsen ACS [4]\n\n**Incentive Spirometry:**\nStart in ED — shown to **prevent development of ACS** during hospitalization. [1]\n\n**AVOID corticosteroids** — risk of rebound pain, stroke, and other complications. [4][5]","citation":[1,4,5,8],"next":"scd-voc-reassess","summary":"Ketorolac + opioid IV; NS 10mL/kg bolus; incentive spirometry q2h prevents ACS; AVOID corticosteroids — rebound pain and stroke risk","safetyLevel":"warning"}'::jsonb
WHERE id = 'scd-voc-iv' AND tree_id = 'sickle-cell';

-- Node: scd-fever-workup (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Fever — Workup","body":"**Obtain BEFORE antibiotics:**\n• Blood culture (ALWAYS — regardless of how well the patient appears) [1][4]\n\n**Laboratory Studies:**\n• CBC with differential + reticulocyte count\n• CMP (comprehensive metabolic panel)\n• Urinalysis if UTI concern\n\n**Imaging:**\n• **CXR if ANY respiratory symptoms** (cough, chest pain, hypoxia, tachypnea) — evaluate for ACS [1]\n\n**Additional Assessment:**\n• Vaccination status — PCV15/PCV20, PPSV23, meningococcal\n• Penicillin prophylaxis compliance\n• Central line → increased bacteremia risk\n• History of splenectomy → increased bacteremia risk\n\n**Viral Testing:**\n• Comprehensive viral testing is optional\n• A **positive viral test does NOT exclude bacteremia** in SCD [1]\n\n**Age <60 days:**\n• Full sepsis workup per AAP 2021 guidelines [1][23]","citation":[1,4,11,12,23],"next":"scd-fever-abx","summary":"Blood culture ALWAYS before abx, CXR if any respiratory symptoms; positive viral test does NOT exclude bacteremia in SCD"}'::jsonb
WHERE id = 'scd-fever-workup' AND tree_id = 'sickle-cell';

