-- Node: na-hypo-adrenal (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Adrenal Insufficiency","body":"**Cortisol deficiency causes hyponatremia through two mechanisms:**\n• Cortisol tonically inhibits ADH — deficiency leads to unopposed ADH secretion\n• Reduced cardiac output and GFR → nonosmotic ADH release\n\n**Diagnosis:**\n• AM cortisol <3 mcg/dL → virtually diagnostic\n• AM cortisol 3-18 mcg/dL → cosyntropin stimulation test\n• AM cortisol >18 mcg/dL → AI unlikely\n• Check ACTH to distinguish primary (high ACTH) from secondary (low ACTH)\n\n**If hemodynamically unstable:**\n• **Stress-dose hydrocortisone 100 mg IV** immediately — do NOT wait for cortisol results\n• Then 50 mg IV q8h until stable\n• Normal saline for volume resuscitation\n\n**If stable:**\n• Draw cortisol/ACTH, then start hydrocortisone 15 mg AM / 5 mg PM\n• Na+ corrects as cortisol is replaced\n• Monitor for overcorrection — ADH suppresses once cortisol is adequate","citation":[1,2,3],"recommendation":"Check AM cortisol and ACTH. If hemodynamically unstable, give stress-dose hydrocortisone 100 mg IV stat (do not wait for results), then 50 mg IV q8h. If stable, draw labs then start physiologic replacement (15 mg AM / 5 mg PM). Na+ corrects as cortisol is replaced. Monitor for overcorrection once ADH suppresses. Endocrinology consult for all new adrenal insufficiency diagnoses.","treatment":{"firstLine":{"drug":"Hydrocortisone","dose":"100 mg (stress dose) or 15 mg AM/5 mg PM (physiologic)","route":"IV (stress) or PO (physiologic)","frequency":"Stress: 100 mg stat then 50 mg q8h. Physiologic: BID","duration":"Until hemodynamically stable, then transition to maintenance","notes":"Do NOT wait for cortisol results if unstable. Na+ corrects as cortisol is replaced."},"monitoring":"Monitor for Na+ overcorrection once ADH suppresses. Check cortisol response. Endocrinology consult."}}'::jsonb
WHERE id = 'na-hypo-adrenal' AND tree_id = 'sodium';

-- Node: stroke-evt-window (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"EVT Eligibility (6–24h)","body":"**Anterior circulation (DAWN/DEFUSE-3 criteria):**\n• NIHSS ≥6\n• ICA or M1 occlusion on CTA\n• Small ischemic core on CT perfusion (<70 mL at 6–16h; <21 mL at 16–24h)\n• Large penumbra with mismatch ratio >1.8\n\n**Posterior circulation (basilar artery):**\n• NIHSS ≥10\n• Basilar artery occlusion on CTA\n• PC-ASPECTS ≥6\n• Up to 24h from onset (ATTENTION trial)","citation":[6,7,8],"options":[{"label":"Meets EVT criteria","description":"LVO + favorable perfusion profile","next":"stroke-evt-eligible","urgency":"critical"},{"label":"Does not meet criteria","description":"Large core, no LVO, or unfavorable imaging","next":"stroke-antiplatelet-start"}],"summary":"EVT 6-24h window: DAWN/DEFUSE-3 criteria for anterior (NIHSS >=6, ICA/M1, small core), ATTENTION for basilar up to 24h"}'::jsonb
WHERE id = 'stroke-evt-window' AND tree_id = 'stroke';

-- Node: stroke-dapt (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":4,"title":"Dual Antiplatelet Therapy (DAPT)","body":"**Loading (Day 1):**\n• [Aspirin](#/drug/aspirin/stroke) 325 mg + [Clopidogrel](#/drug/clopidogrel/stroke) 300 mg\n\n**Maintenance:**\n• Aspirin 81 mg + Clopidogrel 75 mg daily × 21 days\n• Then single antiplatelet (either agent)\n\n**Alternative (CYP2C19 poor metabolizer):**\n• [Ticagrelor](#/drug/ticagrelor/stroke) 180 mg load + Aspirin 300 mg, then Ticagrelor 90 mg BID × 90 days total + Aspirin 81 mg × 21 days only — aspirin discontinued after day 21, ticagrelor continues alone through day 90 (CHANCE-2 protocol)\n\nPOINT trial: DAPT (dual antiplatelet therapy) reduced 90-day stroke from 6.5% to 5.0% (NNT 67). Duration beyond 21 days increases bleeding without additional benefit.\n\nAlso initiate statin (high-intensity) and complete stroke workup (telemetry, echo, vascular imaging).","citation":[3,9,10,12],"recommendation":"Start DAPT immediately. Limit duration to 21 days. Add high-intensity statin. Complete stroke etiology workup.","treatment":{"firstLine":{"drug":"Aspirin + Clopidogrel","dose":"Load: Aspirin 325 mg + Clopidogrel 300 mg; Maintenance: Aspirin 81 mg + Clopidogrel 75 mg","route":"PO","frequency":"Daily","duration":"21 days, then single antiplatelet","notes":"Do NOT extend DAPT beyond 21 days (increases bleeding without benefit)"},"alternative":{"drug":"Ticagrelor + Aspirin","dose":"Load: Ticagrelor 180 mg + Aspirin 300 mg; Days 2-21: Ticagrelor 90 mg BID + Aspirin 81 mg; Days 22-90: Ticagrelor 90 mg BID alone","route":"PO","frequency":"Ticagrelor BID, Aspirin daily (days 1-21 only)","duration":"90 days total (aspirin discontinued after day 21)","notes":"For CYP2C19 poor metabolizers who cannot activate clopidogrel (CHANCE-2 protocol)"},"monitoring":"Monitor for bleeding (GI, intracranial). Complete stroke etiology workup. Add high-intensity statin."},"confidence":"definitive"}'::jsonb
WHERE id = 'stroke-dapt' AND tree_id = 'stroke';

-- Node: sui-means (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Means Restriction Counseling","body":"**Lethal means restriction SAVES LIVES**\n\n**Most lethal methods:**\n• Firearms (~90% case fatality)\n• Drowning (56%)\n• Hanging/suffocation (53%)\n• Poisoning/overdose (~2%)\n\n**Key point:** 90% who survive an attempt do NOT die by suicide later.\nReducing access to lethal means prevents impulsive deaths.\n\n**CALM approach:**\n• **C**larify if means are accessible\n• **A**sk about willingness to secure\n• **L**isten to barriers\n• **M**ake a plan together","citation":[6],"next":"sui-means-firearms","summary":"Means restriction saves lives. Firearms = ~90% case fatality. Use CALM approach."}'::jsonb
WHERE id = 'sui-means' AND tree_id = 'suicidal-patient';

-- Node: sync-abnormal-ecg (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Abnormal ECG — High-Risk Feature","body":"**Abnormal ECG is a high-risk feature in all syncope risk stratification tools.** [1,2,10]\n\nECG findings associated with serious cardiac arrhythmias within 30 days: [9]\n• Nonsinus rhythm\n• Mobitz II or third-degree AV block\n• Bundle branch block (especially new LBBB)\n• QTc >460 ms\n• Pre-excitation (WPW)\n• Brugada type 1 pattern\n• Epsilon waves (ARVC)\n• \"Dagger\" Q waves (HCM)\n• ST depression or T-wave inversions\n\nAtrial fibrillation, IVCD, LVH, and ventricular pacing are independent predictors of mortality. [11]\n\nContinue to history assessment — ECG findings will factor into risk stratification.","citation":[1,2,9,10,11],"next":"sync-history","summary":"Abnormal ECG = high-risk in ALL syncope tools — BBB, QTc >460, pre-excitation, Brugada, epsilon waves","safetyLevel":"warning"}'::jsonb
WHERE id = 'sync-abnormal-ecg' AND tree_id = 'syncope';

-- Node: sync-labs (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Laboratory Testing","body":"**Labs are low-yield unless directed by history/exam.** [1,2]\n\nConsider in patients without clear benign diagnosis:\n• **CBC** — anemia (but initial Hgb may be normal in acute hemorrhage)\n• **BMP** — electrolytes, renal function, glucose\n• **Pregnancy test** — all women of childbearing age\n• **Troponin (hs-cTnT)** — elevated troponin is an independent predictor of 30-day mortality [13]\n• **BNP/NT-proBNP** — elevated BNP confers ~8× increased risk of serious outcomes; may distinguish cardiac from vasovagal [14,15]\n• **Lactate** — if seizure vs syncope unclear (within 2 hours)\n\n**Do NOT routinely obtain:**\n• D-dimer (unless PE otherwise suspected by PERC/Wells)\n• Head CT (unless neuro deficit or head trauma)\n• EEG (unless seizure suspected)\n• Stress testing (unless exertional syncope with ischemia concern)","citation":[1,2,7,13,14,15,16],"next":"sync-risk-stratify","summary":"Labs low-yield unless directed — troponin predicts 30-day mortality; do NOT routinely D-dimer or head CT","skippable":true}'::jsonb
WHERE id = 'sync-labs' AND tree_id = 'syncope';

-- Node: sync-orthostatic (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Orthostatic Hypotension","body":"Orthostatic hypotension = **SBP drop >20 mmHg (or DBP drop >10 mmHg) within 3 minutes of standing**, or symptoms with position change. [1]\n\nMost common cause: **medications** (~40% of cases). [22]\n\n**Drug-related causes:**\n• Antihypertensives (ACEi, ARBs, beta-blockers, CCBs)\n• Diuretics\n• Alpha-blockers (tamsulosin, doxazosin)\n• Nitrates\n• Antidepressants (TCAs, MAOIs)\n• Antipsychotics\n\n**Other causes:** volume depletion, autonomic failure (diabetes, Parkinson), adrenal insufficiency\n\n**Important:** Orthostatic hypotension does NOT exclude more serious causes, especially in the elderly. One study found no difference in 30-day serious outcomes between elderly patients with normal vs abnormal orthostatic vitals. [23]\n\nIs the orthostatic hypotension clearly **medication-related or volume-related** with an otherwise reassuring workup?","citation":[1,22,23],"options":[{"label":"Yes — Clear medication/volume cause","description":"Modifiable cause identified, otherwise low-risk","next":"sync-orthostatic-disposition"},{"label":"No — Other risk factors present","description":"Elderly with comorbidities, unclear cause","next":"sync-risk-stratify"}]}'::jsonb
WHERE id = 'sync-orthostatic' AND tree_id = 'syncope';

-- Node: sync-cardiac-workup (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Cardiac Syncope Workup","body":"**Structural heart disease + syncope = HIGH RISK.** [1,2,25]\n\n**Recommended ED workup:**\n• Continuous telemetry monitoring (minimum 6 hours for high-risk) [8]\n• Troponin (hs-cTnT) — elevated is independent predictor of 30-day mortality [13]\n• BNP/NT-proBNP — aids in recognition of cardiac syncope [14,15]\n• Echocardiography — high yield when HF, CAD, abnormal ECG, or elevated biomarkers present [26]\n\n**Consider echocardiography** if:\n• History of heart failure\n• Coronary artery disease\n• Abnormal ECG\n• Elevated hs-cTnT or NT-proBNP\n\nOtherwise, echo has low yield for most syncope patients. [26,27]","citation":[1,2,8,13,14,15,25,26,27],"next":"sync-risk-stratify","summary":"Structural heart disease + syncope = HIGH RISK — troponin, BNP, echo if HF/CAD/abnormal ECG/elevated biomarkers","safetyLevel":"warning"}'::jsonb
WHERE id = 'sync-cardiac-workup' AND tree_id = 'syncope';

-- Node: sync-elderly (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Elderly Syncope","body":"**Particularly challenging** — many present with unexplained falls rather than syncope. [37,38]\n\n**Key points:**\n• 25-50% of unexplained falls in elderly may be syncope-related [37,39]\n• Almost half of elderly with dementia referred for unexplained falls receive a syncope diagnosis [39]\n• Neurally mediated syncope is still common in this age group [37]\n• QTc prolongation occurs in 25% of elderly — QTc >500 ms predicts 30-day and 1-year mortality [40,41]\n\n**Hospitalization controversy:**\n• Older adults often have multiple risk factors and worse outcomes overall\n• However, for unexplained syncope WITHOUT a serious ED diagnosis, **hospitalization does not improve 30-day adverse outcomes** [42]\n• Age >65 alone and unexplained syncope are NOT independent predictors of mortality [43,44]\n• Mortality is related primarily to **underlying comorbidities**, not the syncope itself [42,45]\n\nHospitalization may increase likelihood of identifying a serious diagnosis, but does not appear to improve mortality.","citation":[37,38,39,40,41,42,43,44,45],"summary":"25-50% of elderly falls may be syncope — hospitalization does not improve 30-day outcomes; mortality from comorbidities","skippable":true}'::jsonb
WHERE id = 'sync-elderly' AND tree_id = 'syncope';

-- Node: sync-disposition-intermediate (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Intermediate Risk — Observation vs. Outpatient","body":"**Shared decision-making recommended.** [1,2]\n\n**Intermediate-risk factors:** [1]\n• Age ≥50 years\n• Prior history of cardiac disease\n• Cardiac device without dysfunction\n• Family history of early sudden cardiac death\n• Symptoms not consistent with reflex-mediated syncope\n\n**Key point:** Patients with risk factors by PMH (CAD, HF) but with a **benign cause identified in the ED** (e.g., dehydration) may be discharged safely. [46]\n\n**If observation/discharge:**\n• Structured ED observation protocol may reduce admissions [47]\n• Ensure close follow-up (PCP, cardiology)\n• Consider referral for:\n  - Ambulatory ECG monitoring (Holter, event monitor)\n  - Tilt-table testing\n  - Implantable loop recorder\n  - Electrophysiology evaluation [1]\n\n**If admitted:**\n• Telemetry monitoring\n• Targeted workup based on risk profile","citation":[1,2,45,46,47],"recommendation":"Shared decision-making. Consider ED observation protocol. If discharge: close follow-up + ambulatory monitoring referral.","confidence":"recommended"}'::jsonb
WHERE id = 'sync-disposition-intermediate' AND tree_id = 'syncope';

-- Node: sync-disposition-low (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":6,"title":"Low Risk — Discharge","body":"**Low-risk patients should generally be discharged**, even with unexplained syncope. [1,2]\n\n**Low-risk features (ESC):** [2]\n• Young age with typical features of reflex syncope\n• No history of cardiac disease\n• Syncope only when standing\n• Identifiable trigger (pain, blood, prolonged standing)\n• Normal ECG\n• Normal vital signs\n\n**Discharge counseling:**\n• Explain diagnosis and expected benign prognosis\n• Counsel on avoidance of known triggers\n• Counterpressure maneuvers (leg crossing, hand gripping) for prodromal symptoms\n• Adequate hydration and salt intake\n• Review fall risk and injury prevention\n\n**Recurrence:** ~9% recurrence within 6 months; 3+ lifetime episodes most predictive of future recurrence [48]\n\n**Driving:** Be familiar with state laws regarding driving after syncope. Consider referral before return to work for commercial drivers or high-risk occupations. [49]\n\n**Follow-up:** PCP for recurrent or unexplained syncope.\n\n[Discharge Instructions](#/info/syncope-discharge) — shareable patient handout","citation":[1,2,47,48,49],"recommendation":"Discharge with reassurance, trigger avoidance counseling, and PCP follow-up. Address driving restrictions if applicable. Review [Discharge Instructions](#/info/syncope-discharge) with patient.","confidence":"definitive"}'::jsonb
WHERE id = 'sync-disposition-low' AND tree_id = 'syncope';

-- Node: sync-no-head-ct (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Head CT Is NOT Indicated","body":"**ACEP \"Choosing Wisely\" recommendation:** Avoid head CT in asymptomatic patients with syncope, minimal trauma, and a normal neurologic examination. [16]\n\n**Evidence:**\n• Head CT has very low yield (<0.1%) in determining the cause of syncope [50]\n• Commonly ordered despite lack of utility — one study found 58% of pediatric syncope patients received head CT [36]\n• No neurological symptoms + no head trauma + normal neuro exam = **no head CT needed** [16,50]\n\n**Only obtain head CT if:**\n• Significant head trauma from the fall\n• Neurological deficit on examination\n• Suspicion for SAH (thunderclap headache)","citation":[16,36,50],"summary":"ACEP Choosing Wisely: no head CT without neuro deficit or head trauma — <0.1% yield for syncope cause","skippable":true}'::jsonb
WHERE id = 'sync-no-head-ct' AND tree_id = 'syncope';

-- Node: sync-pe-screening (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Pulmonary Embolism & Syncope","body":"**PE is uncommon among syncope patients.** [51,52]\n\nExisting clinical decision rules (PERC) adequately identify syncope patients with PE. [51]\n\n**Routine D-dimer is NOT indicated** in syncope patients without independent indications for PE evaluation. [53,54]\n\n**When to consider PE:**\n• Unexplained persistent tachycardia, hypotension, tachypnea, or hypoxia in ED\n• Recent surgery, immobilization, or other VTE risk factors\n• Syncope + dyspnea + pleuritic chest pain\n\n**Apply standard PE rules** (PERC → Wells → CTPA) only when clinically indicated — do NOT screen all syncope patients for PE.","citation":[51,52,53,54],"summary":"Routine D-dimer NOT indicated — PE uncommon in syncope; apply standard PERC/Wells only when clinically suspected","skippable":true}'::jsonb
WHERE id = 'sync-pe-screening' AND tree_id = 'syncope';

-- Node: sync-carotid-massage (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Carotid Sinus Massage","body":"**AHA and ESC recommend carotid sinus massage** in patients >40 years with undiagnosed syncope after initial evaluation. [1,2]\n\nDiagnostic in up to 60% of patients (increasing with advanced age). [19]\n\n**Positive result (carotid sinus hypersensitivity):**\n• Syncope reproduced, OR\n• Asystole >3 seconds, OR\n• AV block, OR\n• SBP drop ≥50 mmHg\n\n**Contraindications:**\n• Carotid bruit\n• Known carotid stenosis >70%\n• History of TIA or stroke within 3 months\n• MI within 3 months\n• History of VT or VF\n\n**Complication rate:** ~0.1% neurologic complications — careful patient selection is important. [55]\n\nPerform with **appropriate monitoring and resuscitation equipment** readily available.","citation":[1,2,19,55],"summary":"Carotid sinus massage for undiagnosed syncope >40y — diagnostic in up to 60%; contraindicated if carotid bruit/stenosis","skippable":true}'::jsonb
WHERE id = 'sync-carotid-massage' AND tree_id = 'syncope';

-- Node: thyroid-storm-no-bb (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Reduced EF / Heart Failure — Avoid Beta-Blockers","body":"**If EF is reduced or clinical signs of decompensated heart failure: do NOT give beta-blockers.** [2]\n\n**Manage tachycardia by treating the storm:**\n1. Aggressive multimodal thyroid storm treatment (steps 2-7) will reduce heart rate as thyroid hormone levels fall\n2. **[Digoxin](#/drug/digoxin/a-fib rate control)** 0.25-0.5 mg IV — lacks negative inotropic properties. However, thyrotoxicosis increases renal clearance and Vd, so higher doses may be needed and response may be blunted [2]\n3. [Diltiazem](#/drug/diltiazem/a-fib rate control) with extreme caution ONLY if rate control is desperate — still carries negative inotropic risk\n4. **Vasopressor selection:** Phenylephrine (pure alpha — no beta stimulation) or vasopressin. Avoid catecholamines that worsen tachycardia (norepinephrine, epinephrine)\n\n**Permissive tachycardia:** Targeting HR <130 may be more realistic and safer than aggressive rate control in decompensated HF + thyroid storm. [2]\n\n**Cardiogenic pulmonary edema:** NIV (BiPAP) for respiratory support. These patients are often intravascularly depleted despite pulmonary edema — diuretics may worsen hemodynamics. [14]","citation":[2,14],"next":"thyroid-storm-dispo","treatment":{"firstLine":{"drug":"Digoxin","dose":"0.25-0.5 mg","route":"IV","frequency":"Load, then per digoxin protocol","duration":"Until rate controlled","notes":"No negative inotropy. May need higher doses in thyrotoxicosis (increased Vd, renal clearance). Response may be blunted."},"monitoring":"HR target <130 (permissive). Digoxin level. Avoid beta-blockers with reduced EF."},"summary":"Reduced EF: NO beta-blockers — treat the storm; digoxin for rate (no negative inotropy); permissive tachy HR <130","safetyLevel":"critical"}'::jsonb
WHERE id = 'thyroid-storm-no-bb' AND tree_id = 'thyroid';

-- Node: tia-canadian-score (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Canadian TIA Score (Preferred)","body":"**13 Variables - Superior to ABCD2**\n\n**Clinical (9):**\n| Variable | Points |\n|----------|--------|\n| First TIA ever | +2 |\n| Duration >=10 min | +2 |\n| History of carotid stenosis | +2 |\n| On antiplatelet therapy | +3 |\n| Gait disturbance | +1 |\n| Unilateral weakness | +1 |\n| History of vertigo | -3 |\n| DBP >=110 mmHg | +3 |\n| Dysarthria or aphasia | +1 |\n\n**Investigation (4):**\n| Variable | Points |\n|----------|--------|\n| Afib on ECG | +2 |\n| Infarction on CT | +1 |\n| Platelets >=400 | +2 |\n| Glucose >=270 mg/dL | +3 |\n\n**7-Day Risk:**\n| Category | Score | Risk |\n|----------|-------|------|\n| Low | <=3 | 0.5% |\n| Medium | 4-8 | 2.3% |\n| High | >=9 | 5.9% |\n\n**Validation:** AUC 0.70 vs ABCD2 0.60 (p<0.001) in 7,607 patients. [4]","citation":[4],"next":"tia-high-risk-features","calculatorLinks":[{"id":"tia-canadian-score","label":"Canadian TIA Calculator"}],"summary":"13-variable score with investigation findings — superior to ABCD2, 5 risk tiers from minimal to critical","skippable":true}'::jsonb
WHERE id = 'tia-canadian-score' AND tree_id = 'tia-workup';

-- Node: tia-labs (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Laboratory Studies","body":"**Required Labs:**\n\n| Test | Rationale |\n|------|-----------|\n| **Fingerstick glucose** | Hypoglycemia mimic |\n| **CBC** | Anemia, thrombocytosis, polycythemia |\n| **BMP/CMP** | Electrolytes, renal function (for contrast) |\n| **PT/INR, PTT** | Baseline before anticoagulation |\n| **Lipid panel** | Guides statin therapy |\n| **HbA1c** | Undiagnosed diabetes |\n\n**Consider:**\n| Test | When |\n|------|------|\n| **Troponin** | Cardiac symptoms, concern for MI |\n| **TSH** | Afib detected |\n| **Hypercoagulable panel** | Young patient, no risk factors, cryptogenic |\n\n**Key Finding for Canadian TIA Score:**\n- Glucose >=270 mg/dL = +3 points\n- Platelets >=400 = +2 points [1][2]","citation":[1,2],"next":"tia-brain-imaging","summary":"Glucose, CBC, BMP, coags, lipids, HbA1c — glucose >=270 and platelets >=400 affect Canadian TIA score","skippable":true}'::jsonb
WHERE id = 'tia-labs' AND tree_id = 'tia-workup';

-- Node: tia-large-artery (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Large Artery Atherosclerosis","body":"**Carotid Stenosis Management:**\n\n| Stenosis | Management |\n|----------|------------|\n| <50% | Medical management only |\n| 50-69% | Consider CEA/CAS, medical reasonable |\n| >=70% | CEA/CAS recommended if life expectancy >5 years |\n\n**Timing is Critical:**\n- **Within 2 weeks** of TIA for symptomatic stenosis >=50%\n- **CEA preferred over CAS** if within 7 days (lower stroke risk)\n- NNT = 5 if CEA performed within 2 weeks of symptom onset\n- NNT = 125 if delayed beyond 12 weeks\n\n**CEA vs CAS:**\n| | CEA | CAS |\n|---|-----|-----|\n| **Preferred if** | Within 2 weeks, age >70 | High surgical risk, radiation, prior CEA |\n| **Early stroke risk** | 1.4% if within 2 weeks | 8.3% if within first week |\n\n**Intracranial Stenosis:**\n- Medical management preferred (SAMMPRIS trial)\n- Consider intervention only if refractory [1][5]","citation":[1,5],"next":"tia-treatment-intro","summary":"Symptomatic stenosis >=50% needs CEA/CAS within 2 weeks — NNT=3 if done within 2 weeks"}'::jsonb
WHERE id = 'tia-large-artery' AND tree_id = 'tia-workup';

-- Node: tia-dapt-treatment (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"DAPT: POINT/CHANCE Protocol","body":"**Indication:** High-risk TIA (ABCD2 >=4) or minor stroke (NIHSS <=3), non-cardioembolic.\n\n**Based on CHANCE and POINT Trials:**\n\n**LOADING:**\n- Aspirin 162-325 mg (if not already on)\n- Clopidogrel 300-600 mg loading dose\n\n**MAINTENANCE:**\n- Aspirin 81 mg daily\n- Clopidogrel 75 mg daily\n\n**DURATION:**\n- 21 days of DAPT (optimal per pooled analysis)\n- Then transition to aspirin monotherapy\n\n**TIMING:**\n- Ideally within 12-24 hours of symptom onset\n- May consider up to 7 days after onset\n\n**Who NOT to give DAPT:**\n- Cardioembolic TIA (needs anticoagulation)\n- Moderate-severe stroke (NIHSS >3)\n- High bleeding risk\n- Already on anticoagulation [6][7][8]","citation":[6,7,8],"next":"tia-statin-treatment","treatment":{"firstLine":{"drug":"Clopidogrel","dose":"300-600 mg loading, then 75 mg daily","route":"PO","frequency":"Daily after load","duration":"21 days","notes":"Give with aspirin 81 mg daily. Load both if not already on aspirin."},"alternative":{"drug":"Aspirin","dose":"162-325 mg loading, then 81 mg daily","route":"PO","frequency":"Daily","duration":"Long-term after 21 days of DAPT","notes":"Continue aspirin monotherapy indefinitely after DAPT period."},"monitoring":"Monitor for bleeding. Reassess at 21 days for transition to aspirin monotherapy."},"calculatorLinks":[{"id":"tia-dapt-protocol","label":"DAPT Dosing Calculator"}],"summary":"ASA 162-325mg + clopidogrel 300-600mg load, then 81mg + 75mg daily x 21 days, then ASA monotherapy"}'::jsonb
WHERE id = 'tia-dapt-treatment' AND tree_id = 'tia-workup';

-- Node: tia-disposition-intro (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Disposition Overview","body":"**Disposition Options:**\n\n1. **Admit** - For high-risk features or incomplete workup\n\n2. **ED Observation (23-hour)** - Moderate risk, can complete workup\n\n3. **Discharge with rapid follow-up** - Low risk with complete workup\n\n**Key Questions:**\n- Are high-risk features present?\n- Is workup complete (or can it be completed rapidly)?\n- Is rapid TIA clinic available (<48 hours)?\n- Can patient recognize warning signs and return?\n\n**EXPRESS Trial Lesson:**\n- Rapid assessment (<1 day) vs delayed (3 days)\n- 80% reduction in 90-day stroke risk (2.1% vs 10.3%)\n- Speed matters more than setting [1][2][9]","citation":[1,2,9],"next":"tia-admission-criteria","calculatorLinks":[{"id":"tia-disposition","label":"Disposition Calculator"}],"summary":"EXPRESS trial: rapid assessment (<1 day) = 80% reduction in 90-day stroke risk — speed matters more than setting"}'::jsonb
WHERE id = 'tia-disposition-intro' AND tree_id = 'tia-workup';

