-- Node: ti-rabies (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Rabies Exposure","body":"# Rabies Exposure\n\n**Critical Point: Rabies is 100% fatal once symptomatic**\n\n**Exposure Assessment:**\n- **Animal bite or scratch** (dog, bat, monkey, cat)\n- **Bat exposure** (even without visible bite - prophylaxis recommended)\n- **Mucous membrane contact** with saliva\n- Travel to endemic areas (Asia, Africa, Latin America)\n\n**High-Risk Animals:**\n- Dogs (most common worldwide)\n- Bats (US)\n- Monkeys\n- Cats\n- Foxes, raccoons, skunks\n\n**Post-Exposure Prophylaxis (PEP) - DO NOT DELAY:**\n\n**Previously Unvaccinated:**\n1. **Wound care** (thorough washing with soap & water x15 minutes)\n2. **Human rabies immune globulin (HRIG)**\n   - 20 IU/kg\n   - **Infiltrate wound site** (as much as possible)\n   - Give remainder IM at distant site from vaccine\n3. [Rabies vaccine](#/drug/rabies-vaccine/unvaccinated immunocompetent)\n   - 4-dose series: days 0, 3, 7, 14 (immunocompetent)\n   - **Immunocompromised: 5-dose series (add day 28) + check rabies titer**\n   - IM (deltoid, NOT gluteal)\n   - HRIG can be given up to day 7 if not given at day 0\n\n**Previously Vaccinated:**\n- **No HRIG** needed\n- **Rabies vaccine only**: 2 doses (days 0, 3)\n\n**DO NOT WAIT for animal observation or testing**\n- Start PEP immediately if high-risk exposure\n- Can discontinue if animal tests negative or healthy after 10-day observation\n\n**When to Give PEP:**\n- **Definitely:** bat exposure (even without visible bite), unprovoked bite from wild animal, bite from high-risk domestic animal in endemic area\n- **Probably:** provoked bite from wild carnivore/bat, bite from high-risk domestic animal\n- **Probably not:** bite from low-risk domestic animal that can be observed\n\n**Disposition:**\n- **Start PEP in ED** (HRIG + first vaccine dose)\n- Arrange follow-up for remaining vaccine doses\n- **Public health notification**\n- Animal control involvement for observation/testing\n\n**If Symptomatic Rabies (Almost Never Happens):**\n- **Always fatal** once symptoms develop\n- Supportive care only\n- **Strict isolation**","citation":[1]}'::jsonb
WHERE id = 'ti-rabies' AND tree_id = 'traveler-infections';

-- Node: vert-hints-peripheral (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Peripheral HINTS → Vestibular Neuritis","body":"**HINTS \"INFARCT\" mnemonic — remember the CENTRAL (stroke) pattern:**\n• **I**mpulse **N**ormal\n• **F**ast-phase **A**lternating (direction-changing nystagmus)\n• **R**efixation on **C**over **T**est (skew)\n\nAny of these findings = think INFARCT (central stroke), not peripheral. **Peripheral (reassuring) is the opposite pattern** — the one this patient has: **unidirectional nystagmus + abnormal HIT (catch-up saccade) + no skew + normal hearing**.\n\n**Diagnostic accuracy (Kattah 2009):**\n• Sensitivity for stroke: **100%**\n• Specificity: **96%**\n• NPV: 100% (within operator expertise)\n• Outperformed early MRI-DWI in first 48 hours\n\n**⚠️ Critical caveats:**\n• Requires training and practice — non-neurologist sensitivity is lower (Nelson 2011 showed residents had poor accuracy)\n• Only valid in true AVS with spontaneous nystagmus\n• Cannot detect strokes that occur in patients without clear AVS presentation\n• Missing HINTS technique subtleties (e.g., not removing fixation) leads to errors\n\n**Diagnosis: Vestibular Neuritis** (if no hearing loss) or **Labyrinthitis** (if hearing loss without central findings — rare, still warrants MRI).\n\n**Presumed etiology:** Reactivation of HSV-1 in the vestibular ganglion. Self-limited over days to weeks.","citation":[2,11,14,27],"next":"vert-vn-treatment","summary":"All HINTS peripheral: unidirectional nystagmus + abnormal HIT + no skew + normal hearing = vestibular neuritis (100% sensitivity)","skippable":true}'::jsonb
WHERE id = 'vert-hints-peripheral' AND tree_id = 'vertigo';

-- Node: vert-vm-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Vestibular Migraine — Acute Treatment","body":"**Acute treatment parallels standard migraine care**, with dopamine antagonists particularly useful due to the dual antiemetic and antimigraine effect.\n\n**First-line (combine):**\n• [Metoclopramide](#/drug/metoclopramide/vestibular migraine) 10 mg IV over 15 min\n• [Diphenhydramine](#/drug/diphenhydramine/vestibular suppressant) 25 mg IV (prevents akathisia from metoclopramide; short-term vestibular symptom relief)\n• IV fluids 1 L NS bolus\n• [Ketorolac](#/drug/ketorolac/migraine) 30 mg IV or 15 mg IV if elderly/renal concern\n• Consider [Magnesium sulfate](#/drug/magnesium-sulfate/migraine) 1-2 g IV over 15 min (especially if history of aura)\n\n**Second-line:**\n• [Prochlorperazine](#/drug/prochlorperazine/migraine) 10 mg IV (alternative to metoclopramide)\n• Dexamethasone 10 mg IV/PO to reduce recurrence within 72h\n\n**Triptans — controversial in vestibular migraine:**\n• No strong evidence of efficacy for vestibular symptoms\n• May be tried if patient has known triptan-responsive migraine\n• **Contraindicated** in basilar migraine, hemiplegic migraine, uncontrolled HTN, recent stroke/MI\n\n**Cross-reference:** See [Migraine Consult](#/tree/migraine) for full treatment protocols.\n\n**For suppression of severe vertigo nausea only:** Ondansetron 4 mg IV is adjunctive.","citation":[1,8,18],"next":"vert-vm-disposition","summary":"Acute VM: metoclopramide 10mg IV + diphenhydramine 25mg IV + ketorolac + IV fluids — triptans controversial, magnesium if aura history"}'::jsonb
WHERE id = 'vert-vm-treatment' AND tree_id = 'vertigo';

-- Node: wct-hyperkalemia (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":1,"title":"Hyperkalemic WCT","body":"**Treatment priority: membrane stabilization**\n\n**Calcium (immediate):**\n• Calcium gluconate 3g IV over 10 min\n• OR Calcium chloride 1g IV (central line preferred)\n• May repeat in 5 min if no ECG improvement\n\n**Shift potassium:**\n• Regular insulin 10 units IV + D50 50mL IV\n• Albuterol 10-20mg nebulized\n• Sodium bicarbonate 50-100 mEq IV (if acidemic)\n\n**Eliminate potassium:**\n• Emergent hemodialysis if severe (K >7) or refractory\n• Kayexalate is too slow for emergency\n\n→ See [Potassium](#/tree/potassium) for full protocol","citation":[3],"next":"wct-end","summary":"Hyperkalemic WCT: calcium first (membrane stabilization), then insulin/glucose + albuterol, HD if severe","safetyLevel":"critical"}'::jsonb
WHERE id = 'wct-hyperkalemia' AND tree_id = 'wide-complex-tachycardia';

